__MATX("orl",{"res":{"ch":[{"pts":[["Citez les parties de l'oreille et l'appareil auquel chacune appartient.","Oreille externe (pavillon + CAE) et oreille moyenne = appareil de transmission ; oreille interne (labyrinthe) = appareil de perception."],["Quel est le rôle de la trompe d'Eustache ?","Conduit ostéo-cartilagineux reliant la caisse du tympan au pharynx : il aère l'oreille moyenne et équilibre la pression de part et d'autre du tympan."],["Quelles sont les trois fonctions de l'oreille moyenne ?","Transmission des ondes sonores (chaîne tympano-ossiculaire), adaptation d'impédance entre milieu aérien et liquidien, protection de l'oreille interne par le réflexe stapédien."],["Où est produit le cérumen et quels sont ses rôles ?","Par les glandes cérumineuses du 1/3 externe du CAE ; il protège les parois, piège les corps étrangers, est antibactérien et élimine les débris de peau."],["Citez les unités fonctionnelles de l'oreille interne et leur rôle.","Cochlée → organe de Corti (audition : signal mécanique → électrique) ; vestibule → macule ; canaux semi-circulaires → crêtes ampullaires (équilibre)."]],"tabs":[{"t":"Tableau résumé : Oreille","h":["Partie","Composants","Rôle"],"r":[["Oreille externe","Pavillon ; CAE (1/3 externe fibro-cartilagineux à glandes cérumineuses, 2/3 internes osseux)","Capter, localiser, amplifier et diriger le son vers le tympan ; cérumen protecteur"],["Oreille moyenne","Caisse du tympan (marteau, enclume, étrier), mastoïde (antre), trompe d'Eustache","Transmission, adaptation d'impédance, protection (réflexe stapédien) ; trompe : aération et équilibre de pression"],["Oreille interne","Cochlée (organe de Corti), vestibule (macule), canaux semi-circulaires (crêtes ampullaires)","Audition (signal mécanique → électrique) et équilibre"],["Appareils","Externe + moyenne = transmission","Interne = perception"]],"c":null}],"imgs":[[132,"Schéma de l'oreille : externe, moyenne, interne"],[133,"Vue otoscopique du tympan"]]},{"pts":[["Citez les parois d'une fosse nasale.","Paroi externe (cornets et méats), paroi supérieure (toit), paroi inférieure (plancher), paroi interne (cloison nasale). En avant : le vestibule nasal."],["Citez au moins trois fonctions du nez.","Olfactive (odorat), respiratoire (seule voie physiologique ; réchauffe, humidifie, purifie l'air), protection (appareil muco-ciliaire, sécrétions), phonatoire (timbre de la voix)."],["Décrivez la pyramide nasale, la cloison et les muqueuses nasales.","Pyramide triangulaire ostéo-cartilagineuse ; cloison : os en arrière, cartilage septal en avant ; muqueuse respiratoire (presque toute la FN) et olfactive (partie supérieure)."]],"tabs":[{"t":"Tableau résumé : Nez","h":["Rubrique","À retenir"],"r":[["Pyramide nasale","Pyramide triangulaire ostéo-cartilagineuse, muqueuse dedans, muscles et peau dehors"],["Fosses nasales","2 fosses séparées par la cloison ; vestibule en avant ; parois : externe (cornets, méats), supérieure (toit), inférieure (plancher), interne (cloison)"],["Muqueuses","Respiratoire (presque toute la FN) ; olfactive (partie supérieure)"],["Cloison","Os en arrière, cartilage septal en avant"],["Fonctions","Olfactive, respiratoire (seule voie physiologique : réchauffe, humidifie, purifie), protection (muco-ciliaire), phonatoire (timbre)"]],"c":null}],"imgs":[[134,"Fosses nasales et coupe de la région nasale"]]},{"pts":[["Nommez les groupes de sinus de la face et leurs rôles.","Antérieurs : maxillaire, frontal, ethmoïdal antérieur (entourent l'orbite, drainent dans le méat moyen). Postérieurs : ethmoïdal postérieur, sphénoïdal. Rôles : conditionnement de l'air, ventilation, drainage des sécrétions."]],"tabs":[{"t":"Tableau résumé : Sinus","h":["","Sinus antérieurs","Sinus postérieurs"],"r":[["Composition","Maxillaire, frontal, ethmoïde antérieur","Ethmoïde postérieur, sphénoïdal"],["Particularités","Entourent l'orbite, drainent dans le méat moyen","—"],["Rôles","Conditionnement de l'air, ventilation, drainage des sécrétions","Idem"]],"c":null}],"imgs":[[135,"Sinus de la face (frontaux, ethmoïdaux, sphénoïdaux, maxillaires)"]]},{"pts":[["Définissez le pharynx et donnez ses dimensions.","Conduit musculo-membraneux de la base du crâne au bord inférieur de C6, continué par l'œsophage ; 13 cm de long ; 5 cm de large en position nasale, 4 cm en position orale et laryngée."],["Énumérez les étages du pharynx et décrivez l'oropharynx.","Nasopharynx (cavum, rhinopharynx : communique avec les FN par les choanes) ; oropharynx (amygdales palatines et piliers, voile du palais, base de langue et vallécules, parois postérieure et latérale) ; hypopharynx (avec le larynx = carrefour aérodigestif, jusqu'à la bouche œsophagienne)."],["Citez les fonctions du pharynx.","Ventilation, déglutition, phonation (résonateur), défenses immunitaires (formations lymphoïdes), digestion (glandes salivaires), goût (papilles linguales), audition."]],"tabs":[{"t":"Tableau résumé : Pharynx","h":["Rubrique","À retenir"],"r":[["Définition","Conduit musculo-membraneux, base du crâne → bord inférieur de C6, continué par l'œsophage"],["Mesures","13 cm de long ; 5 cm de large (nasal), 4 cm (oral), 4 cm (laryngé)"],["Nasopharynx","Cavum/rhinopharynx, derrière les FN, communique par les choanes"],["Oropharynx","Amygdales palatines et piliers, voile du palais, base de langue, vallécules, parois"],["Hypopharynx","Avec le larynx = carrefour aérodigestif ; jusqu'à la bouche œsophagienne"],["Fonctions","Ventilation, déglutition, phonation, immunité, digestion, goût, audition"]],"c":null}],"imgs":[[136,"Coupe sagittale médiane tête et cou ; cavité buccale"]]},{"pts":[["Citez les cartilages du larynx et l'innervation de ses muscles.","Thyroïde (pomme d'Adam), épiglottique, aryténoïdes (portent les cordes vocales), cricoïde (base). Muscles innervés par les nerfs récurrents (branches du pneumogastrique), sauf le crico-thyroïdien (nerf laryngé supérieur)."],["Quelles sont les fonctions du larynx ?","Déglutition (épiglotte ferme le larynx, cordes rapprochées), respiration (glotte ouverte), phonation (glotte fermée, cordes plus ou moins tendues)."],["Décrivez la trachée (définition, longueur, calibre).","Conduit fibro-cartilagineux d'anneaux trachéaux, aplati en arrière ; trachée cervicale 5-6 cm (adulte), 4 cm (enfant) ; calibre 6 mm (1-4 ans), 8 mm (4-8 ans), 10 mm (8-12 ans), 12 mm (adulte)."],["Citez les trois fonctions de la trachée.","Ciliaire (drainage des sécrétions), sécrétoire (film de mucus protecteur, appelé « surfactant » dans le cours), tonique (permet au larynx de monter et descendre, surtout lors de la déglutition)."]],"tabs":[{"t":"Tableau résumé : Larynx et trachée","h":["","Larynx","Trachée"],"r":[["Définition","Organe entre pharynx et trachée","Conduit fibro-cartilagineux d'anneaux, aplati en arrière"],["Structure","Cartilages thyroïde, épiglottique, aryténoïdes, cricoïde","Trachée cervicale 5-6 cm (adulte), 4 cm (enfant)"],["Chiffres / innervation","Nerfs récurrents (pneumogastrique) sauf crico-thyroïdien (laryngé supérieur)","Calibre 6 / 8 / 10 / 12 mm selon l'âge"],["Fonctions","Déglutition, respiration (glotte ouverte), phonation (glotte fermée)","Ciliaire, sécrétoire, tonique"]],"c":null}],"imgs":[[137,"Le larynx : vues antérieure et postérieure"],[138,"Vue de la glotte et des cordes vocales"],[139,"La trachée : faces antérieure et postérieure"]]},{"pts":[["Définissez l'otalgie vraie et l'otalgie fausse.","Otalgie = douleur de l'oreille. Vraie/primitive (otodynie) : lésion de l'oreille. Fausse/secondaire (otalgie réflexe) : lésion extra-auriculaire de voisinage. Traitement = celui de la cause."],["Citez des causes d'otalgie primitive.","Oreille externe : bouchon, CE, otite externe, furoncle, eczéma surinfecté, périchondrite, othématome, zona, traumatismes, tumeurs ; tympan : myringite ; oreille moyenne : OMA, barotraumatisme, OMC, cancers, traumatismes."],["Citez des causes d'otalgie réflexe.","Dentaire (caries, dent de sagesse : otalgie homolatérale), glossites, stomatites, cancer de langue ; oropharynx (pharyngites, angines, phlegmons, apophyse styloïde longue, cancers) ; larynx/hypopharynx (cancers) ; ATM ; sinusites ; œsophage (CE, RGO, hernie hiatale, cancer) ; thyroïdite, rachis cervical."],["Décrivez l'examen clinique d'un patient otalgique.","Otoscopie d'abord (pavillon, CAE, tympan), puis examen ORL complet : oropharyngoscopie, rhinoscopie antérieure et postérieure ; étendu à la cavité buccale, oro/nasopharynx, hypopharynx-larynx, ATM, sinus, paires crâniennes, œsophage."]],"tabs":[{"t":"Tableau résumé : Otalgies","h":["Rubrique","À retenir"],"r":[["Définition","Douleur de l'oreille : vraie (otodynie) ou réflexe (fausse)"],["Causes vraies","Bouchon, CE, otite externe, furoncle, eczéma, périchondrite, othématome, zona, traumatisme, tumeur, myringite, OMA, OMC, cancer"],["Causes réflexes","Dents (homolatérale), glossite, angine, phlegmon, styloïde longue, cancers, ATM, sinusite, œsophage/RGO, thyroïdite, rachis cervical"],["Examen","Otoscopie puis examen ORL complet (oropharynx, rhinoscopie, bouche, ATM, sinus, nerfs, œsophage)"],["Traitement","Celui de la cause"]],"c":null}],"imgs":[]},{"pts":[["Définissez la surdité.","Trouble de l'audition sans présumer l'intensité, allant de l'hypoacousie (baisse de l'acuité) à la cophose (disparition totale de l'ouïe)."],["Citez les types de surdité et leur siège.","Transmission (oreille externe ou moyenne), perception (oreille interne, tympan normal), mixte (les deux appareils)."],["Énumérez les causes des surdités de transmission.","Oreille externe : bouchon de cérumen (coton-tige), bouchon épidermique, CE, otites externes, ostéomes, tumeurs, atrésie congénitale. Oreille moyenne : OMA, OMC, traumatismes (spontanés, chirurgicaux), tumeurs."],["Énumérez les causes des surdités de perception et les signes d'alerte du nourrisson.","Toxiques (aminosides, surtout avec insuffisance rénale), presbyacousie (50-60 ans), traumatiques (sonores, opératoires, accidentelles), congénitales. 0-3 mois : pas de sursaut aux bruits forts, sommeil imperturbable, cri modifié."]],"tabs":[{"t":"Tableau résumé : Surdités","h":["","Transmission","Perception","Mixte"],"r":[["Siège","Oreille externe / moyenne","Oreille interne (tympan normal)","Les deux"],["Causes","Bouchon cérumen/épidermique, CE, otites, ostéomes, tumeurs, atrésie ; OMA, OMC, traumatismes","Aminosides (+ insuffisance rénale), presbyacousie 50-60 ans, traumatismes sonores, congénitales","Association"],["Définition","Trouble de l'audition : de l'hypoacousie à la cophose","—","—"],["Alerte nourrisson (0-3 mois)","Pas de sursaut aux bruits forts, sommeil imperturbable, cri modifié","",""]],"c":null}],"imgs":[]},{"pts":[["Définissez les acouphènes et leurs formes cliniques.","Bruits perçus dans l'oreille ou la tête sans source extérieure, perçus seulement par le malade ; permanents, intermittents ou temporaires ; tintement, chuintement, bourdonnement, sifflement ; uni- ou bilatéraux."],["Citez les causes et le traitement d'urgence des acouphènes.","Causes : surdité brusque, traumatisme auditif (concert, boîte de nuit, pétard), traumatisme crânien, HTA, anémie sévère et insuffisance rénale, stress/dépression. Urgence : vasodilatateurs, corticoïdes, oxygénothérapie, musique, traitement étiologique."]],"tabs":[{"t":"Tableau résumé : Acouphènes","h":["Rubrique","À retenir"],"r":[["Définition","Bruits perçus sans source extérieure, entendus seulement par le malade"],["Clinique","Permanents, intermittents ou temporaires ; tintement, chuintement, bourdonnement, sifflement ; uni/bilatéraux"],["Causes","Surdité brusque, traumatisme auditif ou crânien, HTA, anémie sévère, insuffisance rénale, stress/dépression"],["Traitement d'urgence","Vasodilatateurs, corticoïdes, oxygénothérapie, musique, traitement étiologique"]],"c":null}],"imgs":[]},{"pts":[["Définissez l'othématome et la conduite devant un CE de l'oreille externe.","Othématome : collection de sang entre le périchondre et le cartilage du pavillon. CE fréquents chez l'enfant, relèvent du spécialiste : extraction par lavage ou au crochet, pince à éviter."],["Bouchon de cérumen : signes et traitement.","Cérumen mou jaunâtre qui noircit et durcit ; hypoacousie, bourdonnements, acouphènes, vertiges, oreille bouchée, prurit, douleur. Extraction par lavage après instillation quelques minutes d'un antiseptique moussant pour le ramollir."],["Furoncle du CAE : définition, signes et traitement.","Inflammation des follicules (sébacés) du 1/3 externe du CAE due au staphylocoque, après grattage ; douleur précoce, intense, à la mobilisation du pavillon, à la mastication et à la pression du tragus ; hypoacousie. Traitement : antalgique, anti-inflammatoire, antibiotique général (amoxicilline-ac. clavulanique, oxacilline, pristinamycine)."],["Otite externe diffuse : signes et traitement.","Infection du revêtement cutané de tout le CAE (piscine, traumatisme, eczéma) ; otalgie exacerbée par la pression du tragus et la traction du pavillon, prurit, otorrhée fétide, CAE œdématié, tympan normal. Traitement : nettoyage au SP, gouttes ATB-corticoïde (Panotile, Polydexa, Colicort), méchage si conduit rétréci (changé chaque jour), antalgique ; si perforation : rifamycine (Otofa) ou lincomycine."],["Eczéma, périchondrite et otomycose : signes et traitement.","Eczéma : prurit intense, poussées, complication = otite externe diffuse ; périchondrite : pavillon tuméfié, rouge, fistule, pus à pyocyanique → antibiotique ; otomycose : dépôt blanchâtre + prurit → antimycosiques locaux 2-3 semaines."]],"tabs":[{"t":"Tableau résumé : Pathologies de l'oreille externe","h":["Pathologie","Cause / définition","Signes","Traitement"],"r":[["Othématome","Sang entre périchondre et cartilage du pavillon","Tuméfaction du pavillon","Spécialiste"],["Corps étranger","Fréquent chez l'enfant","Gêne, hypoacousie","Lavage ou crochet (pince à éviter)"],["Bouchon de cérumen","Cérumen durci (coton-tige)","Hypoacousie, bourdonnement, vertiges, oreille bouchée","Antiseptique moussant puis lavage"],["Eczéma","Dermatose par poussées","Prurit intense","Nettoyage, gouttes ATB-corticoïde, ATB si surinfection"],["Furoncle du CAE","Staphylocoque, 1/3 externe, grattage","Douleur intense (tragus, mastication)","Antalgique, AINS, ATB générale"],["Otite externe diffuse","Piscine, traumatisme, eczéma ; tout le CAE","Otalgie (tragus, traction), otorrhée fétide, tympan normal","Nettoyage SP, gouttes ATB-corticoïde, méchage ; Otofa si perforation"],["Périchondrite","Infection/traumatisme du pavillon","Pavillon rouge, fistule, pyocyanique","Antibiotique"],["Otomycose","Champignons","Dépôt blanchâtre + prurit","Antimycosique local 2-3 semaines"]],"c":null}],"imgs":[[141,"Furoncle du conduit auditif externe"]]},{"pts":[["OMA du nourrisson : définition, circonstance et germes.","Inflammation de la muqueuse des cavités de l'oreille moyenne évoluant sur moins de 3 semaines, au décours d'une rhinopharyngite ; H. influenzae, S. pneumoniae, M. catarrhalis, mais le plus souvent virale."],["Signes cliniques et formes otoscopiques de l'OMA.","Fièvre, diarrhée, pleurs, vomissements, rhinite, porte le doigt à l'oreille ; diagnostic par otoscopie : congestive (tympan rouge épaissi, vascularisation du manche du marteau), suppurée collectée (tympan opaque, terne, bombé), suppurée perforée (pus parfois pulsatile, perforation postérieure). Bilatérale > 1 fois sur 2."],["Conduite à tenir devant une OMA du nourrisson.","Vasoconstricteur < 5 jours, désinfection rhinopharyngée au SP, amoxicilline-acide clavulanique 80-100 mg/kg/j, Célestine 10 gouttes/kg/j, paracentèse au stade suppuré collecté ; prévention : hygiène nasale, traiter les allergies, vaccins pneumocoque et Haemophilus."],["Complications et diagnostic différentiel de l'OMA.","OMA récidivantes (adénoïdectomie si végétations), mastoïdite aiguë, paralysie faciale otitique, méningite. Diagnostic différentiel : otite externe, otite séromuqueuse, otite moyenne chronique."]],"tabs":[{"t":"Tableau résumé : OMA du nourrisson","h":["Rubrique","À retenir"],"r":[["Définition","Inflammation de la muqueuse de l'oreille moyenne < 3 semaines, après rhinopharyngite"],["Germes","H. influenzae, pneumocoque, Moraxella ; le plus souvent virale"],["Signes","Fièvre, diarrhée, vomissements, pleurs, rhinite, porte la main à l'oreille ; bilatérale > 1 fois sur 2"],["Otoscopie","Congestive (rouge) → suppurée collectée (bombée) → suppurée perforée (pus)"],["CAT","Vasoconstricteur < 5 j, SP, amox-clav 80-100 mg/kg/j, Célestine 10 gttes/kg/j, paracentèse si collectée"],["Complications","Récidives (adénoïdectomie), mastoïdite, paralysie faciale, méningite"],["Prévention","Hygiène nasale, traiter les allergies, vaccins pneumocoque et Haemophilus"]],"c":null}],"imgs":[[142,"Otite congestive : tympan rouge et épaissi"],[143,"OMA suppurée collectée : tympan bombé"],[144,"OMA suppurée perforée : écoulement de pus"]]},{"pts":[["Définissez l'épistaxis et précisez son origine habituelle.","Saignement d'origine endonasale, antérieur (narine), postérieur (rhinopharynx) ou mixte ; urgence fréquente. 90 % : tache vasculaire de Kisselbach sur la cloison, à ~1 cm de l'entrée narinaire. Bénigne (minime/moyenne) vs grave (abondance/répétition + retentissement hémodynamique)."],["Citez au moins cinq causes d'épistaxis.","HTA (prendre la TA chez tout adulte), traumatiques (fracture OPN, disjonction crânio-faciale, chirurgie), maladies hémorragiques (Rendu-Osler, thrombopénies, hémophilie, anticoagulants, IR, IH), tumorales (angiofibrome juvénile du garçon adolescent, cancers), infectieuses (rhinopharyngites, sinusites, typhoïde, grippe), autres (CE de l'enfant, perforation septale, grossesse)."],["Conduite à tenir devant une épistaxis bénigne.","Mouchage des caillots, pulvérisation lidocaïne 5 % naphazoline, examen des FN, compression bidigitale des ailes du nez 10 min tête penchée en avant (coton à l'eau oxygénée/thrombase) ; si échec : méchage antérieur en accordéon (mèche grasse) retiré au plus tard 48 h (nécrose septale) ; couverture ATB ; vérifier l'arrêt par le pharynx ; si échec : bilan sanguin + ORL."],["Conduite à tenir devant une épistaxis grave.","Hospitalisation, prise de la TA en urgence, voie veineuse (correction d'un choc), groupage (transfusion), tamponnement antérieur voire postérieur, couverture antibiotique et hémostatique parentérale."]],"tabs":[{"t":"Tableau résumé : Épistaxis","h":["Rubrique","À retenir"],"r":[["Définition","Saignement endonasal antérieur, postérieur ou mixte ; urgence fréquente"],["Origine","90 % : tache vasculaire de Kisselbach, cloison à 1 cm de la narine"],["Causes","HTA, traumatismes, maladies hémorragiques (Rendu-Osler, hémophilie, anticoagulants), tumeurs (angiofibrome juvénile), infections, CE, grossesse"],["CAT bénigne","Mouchage, lidocaïne-naphazoline, compression 10 min tête en avant, méchage si échec (≤ 48 h), ATB"],["CAT grave","Hospitalisation, TA, voie veineuse, groupage, tamponnement antérieur/postérieur, ATB + hémostatique IV"]],"c":null}],"imgs":[]},{"pts":[["Définissez les rhinites et citez au moins trois causes.","Inflammations des fosses nasales. Causes/formes : allergiques, infectieuses (aiguës < 12 sem, chroniques au-delà), médicamenteuses, endocriniennes, inflammatoires non allergiques (NARES), chimiques/environnementales, idiopathiques."],["Rhinite allergique : signes cliniques et classification.","Triade brutale : obstruction nasale, éternuements en salve, rhinorrhée aqueuse. Intermittente : < 4 j/semaine ou < 4 semaines/an ; persistante : > 4 j/semaine et > 4 semaines/an. Modérée : aucun des 4 critères (sommeil, activités, travail/école, symptômes invalidants) ; sévère : au moins un."],["Rhinites médicamenteuses, endocriniennes et NARES.","Médicamenteuses : aspirine, réserpine, guanéthidine, IEC ; vasoconstricteurs au long cours à forte dose. Endocriniennes : hyperthyroïdie, acromégalie, 3e trimestre de grossesse (œstrogènes). NARES : éosinophiles > 20 % et enquête allergique négative."],["Traitement des rhinites.","Mouchage, vasoconstricteur de courte durée, lavage nasal, antihistaminique, éviction de l'allergène, traitement des symptômes invalidants."]],"tabs":[{"t":"Tableau résumé : Rhinites","h":["Type","Caractéristiques","Traitement / notes"],"r":[["Allergique","Obstruction, éternuements en salve, rhinorrhée aqueuse ; intermittente/persistante (seuil 4 j/4 sem) ; modérée/sévère","Antihistaminique, éviction de l'allergène"],["Infectieuse","Virale, bactérienne, mycosique, parasitaire ; aiguë < 12 sem, chronique au-delà","Mouchage, lavage"],["Médicamenteuse","Aspirine, réserpine, guanéthidine, IEC, vasoconstricteurs prolongés","Arrêt du produit"],["Endocrinienne","Hyperthyroïdie, acromégalie, 3e trimestre de grossesse","—"],["NARES","Éosinophiles > 20 %, enquête allergique négative","—"],["Traitement général","Mouchage, vasoconstricteur court, lavage, antihistaminique, éviction","Lutter contre les symptômes invalidants"]],"c":null}],"imgs":[]},{"pts":[["Définissez la sinusite aiguë et citez ses germes.","Atteinte infectieuse de la muqueuse des sinus de la face évoluant depuis moins de 3 semaines ; après rhinite, grippe, bain en piscine ; H. influenzae, pneumocoque, S. aureus, anaérobies."],["Tableau clinique d'une sinusite maxillaire aiguë.","La plus fréquente, unilatérale (pansinusite si tous les sinus homolatéraux) ; douleur sous-orbitaire unilatérale pulsatile, augmentée tête penchée en avant et à la toux ; céphalée, obstruction, rhinorrhée purulente parfois striée de sang, cacosmie, anosmie ; pus au méat moyen, cornets tuméfiés, douleur à la pression du nerf sous-orbitaire ; Blondeau : opacité du sinus maxillaire."],["Traitement de la sinusite maxillaire aiguë.","Décongestionner les ostiums (lavage du nez) ; antalgiques ; antibiotique général 10 jours (amoxicilline-ac. clavulanique, C3G : Orelox, Texodil, ou pristinamycine : Pyostacine) ; corticothérapie 5 jours à 0,5-1 mg/kg/j (Cortancyl) ; soins locaux (lavage SP, aérosol sonique) ; antihistaminique après l'ATB. Évite la chronicité."]],"tabs":[{"t":"Tableau résumé : Sinusite maxillaire aiguë","h":["Rubrique","À retenir"],"r":[["Définition","Infection de la muqueuse sinusienne < 3 semaines (après rhinite, grippe, piscine)"],["Germes","H. influenzae, pneumocoque, staphylocoque doré, anaérobies"],["Clinique","Douleur sous-orbitaire unilatérale pulsatile (penché en avant, toux), céphalée, obstruction, rhinorrhée purulente, cacosmie, anosmie"],["Examens","Pus au méat moyen, cornets tuméfiés ; Blondeau : opacité du sinus"],["Traitement","Lavage, antalgique, ATB 10 j (amox-clav, C3G, pristinamycine), cortico 5 j 0,5-1 mg/kg/j, aérosols, antihistaminique après ATB"],["But","Éviter le passage à la chronicité"]],"c":null}],"imgs":[]},{"pts":[["Définissez les végétations adénoïdes.","Hypertrophie du tissu lymphoïde de la paroi postéro-supérieure du rhinopharynx due aux infections respiratoires répétées : hypertrophie de l'amygdale pharyngée de Luschka."],["Signes cliniques et radiologiques des végétations adénoïdes.","Obstruction nasale bilatérale : respiration buccale, ronflement nocturne, troubles du sommeil ; rhinorrhée mucopurulente = surinfection ; test bouche fermée du nourrisson ; mucopus sur la paroi pharyngée postérieure ; radio de profil du cavum (inspiration, bouche fermée) : espace clair comblé."],["Complications et traitement des végétations adénoïdes.","Tubotympaniques (OMA récidivantes, otites séromuqueuses) ; laryngo-trachéo-bronchiques (laryngites sous-glottiques à répétition, trachéites, bronchopneumopathies) ; rhinosinusiennes (rhinosinusites, ethmoïdite aiguë, adénites cervicales, détresse respiratoire du NN/nourrisson). Traitement : adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil."]],"tabs":[{"t":"Tableau résumé : Végétations adénoïdes","h":["Rubrique","À retenir"],"r":[["Définition","Hypertrophie de l'amygdale pharyngée de Luschka (infections répétées)"],["Signes","Obstruction nasale bilatérale, respiration buccale, ronflement, troubles du sommeil ; rhinorrhée purulente = surinfection"],["Examens","Test bouche fermée ; mucopus pharyngé ; radio de profil du cavum (inspiration, bouche fermée)"],["Complications","OMA récidivantes, otites séromuqueuses, laryngites, trachéites, bronchopneumopathies, sinusites, ethmoïdite, adénites, détresse respiratoire"],["Traitement","Adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil"]],"c":null}],"imgs":[]},{"pts":[["Rhinopharyngite : définition et signes de début.","Inflammation aiguë de la muqueuse des FN et du rhinopharynx, surtout virale, très fréquente chez l'enfant ; fièvre brutale 39-40 °C, irritabilité, vomissements/diarrhée, adénopathies cervicales bilatérales, obstruction nasale bilatérale, rhinorrhée séreuse puis mucopurulente, éternuements, rougeur conjonctivale, larmoiement, toux rauque, cri modifié."],["Examen clinique de la rhinopharyngite.","Rhinoscopie : muqueuse très rouge, mucopus (mucus jaunâtre à polynucléaires et macrophages) ; oropharyngoscopie : muqueuse rouge surtout aux piliers et amygdales ; otoscopie : congestion tympanique."],["Traitement et évolution d'une rhinopharyngite non compliquée.","Désinfection rhinopharyngée pluriquotidienne au SP, aspiration (mouche-bébé), éducation au mouchage ; aspirine 80 mg/kg/j dans le cours (notion datée) ; antibiothérapie inutile ; guérison en 5 jours ; surveillance des complications."],["Citez trois complications de la rhinopharyngite et leur traitement.","OMA (la plus fréquente), laryngite aiguë sus-glottique, trachéobronchite, adénophlegmon du cou, phlegmon rétropharyngé, sinusite maxillaire, ethmoïdite aiguë ; traitement : SP, anti-inflammatoire + antibiotique (amoxicilline ± ac. clavulanique) 8 jours, contrôle à une semaine."]],"tabs":[{"t":"Tableau résumé : Rhinopharyngite","h":["Rubrique","À retenir"],"r":[["Définition","Inflammation aiguë des FN et du rhinopharynx, surtout virale, très fréquente chez l'enfant"],["Signes","Fièvre brutale 39-40 °C, obstruction bilatérale, rhinorrhée séreuse → mucopurulente, signes oculaires, toux rauque, adénopathies"],["Examen","Rhinoscopie (mucopus), oropharyngoscopie (rouge), otoscopie (congestion)"],["Traitement","SP pluriquotidien, mouche-bébé, mouchage ; pas d'ATB si non compliquée ; guérison en 5 jours"],["Complications","OMA (la plus fréquente), laryngite, trachéobronchite, phlegmons, sinusite, ethmoïdite → ATB 8 j"]],"c":null}],"imgs":[]},{"pts":[["Pharyngite aiguë : définition, signes et facteurs de risque.","Inflammation de la gorge/pharynx (streptocoque, virus, champignon), bénigne ; aiguë : quelques jours à 1 semaine, surtout virale ; odynophagie, dysphonie, fièvre modérée 38 °C, céphalées, asthénie, ganglions cervicaux, toux. TROD pour le germe. Facteurs : tabac, alcool, environnement (poussière, air sec/froid, climatisation, gouttes nasales répétées)."],["Pharyngite chronique : définition, signes et causes.","Installation progressive, > 3 semaines, symptômes localisés à la gorge, fièvre seulement si surinfection ; sécheresse, raclage, douleur, odynodysphagie ; plus fréquente chez l'adulte : tabac (actif/passif), alcool, environnement, rhinite, rhinosinusite chronique, RGO, enseignant, chanteur."],["Complications et traitement des pharyngites.","Bactérienne dans 30 % (streptocoque β-hémolytique A) : abcès péripharyngé, otites, sinusites, laryngites, trachéobronchites, pneumonies, glomérulonéphrite aiguë post-streptococcique, RAA. Traitement : lavage de nez, mouchage, boissons chaudes, sprays, paracétamol, ATB seulement si bactérienne."],["Pharyngite mycosique : signes et traitement.","Brûlures ou sensation de coton dans la bouche, dysphagie, agueusie, sécheresse, petits saignements ; plaques blanc crème ; antifongiques : nystatine (Mycostatine) comprimé à sucer, amphotéricine (Fungizone) ou miconazole (Daktarin) gel."]],"tabs":[{"t":"Tableau résumé : Pharyngites","h":["","Aiguë","Chronique","Mycosique"],"r":[["Durée / cause","Quelques jours à 1 semaine, surtout virale","> 3 semaines ; tabac, alcool, RGO, voix","Champignons"],["Signes","Odynophagie, dysphonie, fièvre 38 °C, céphalées, ganglions","Sécheresse, raclage, odynodysphagie, sans fièvre","Brûlures, coton, agueusie, plaques blanc crème"],["Diagnostic","Oropharyngoscopie, TROD","Interrogatoire, palpation, prélèvement","Examen"],["Traitement","Lavage nez, boissons chaudes, paracétamol, ATB si bactérienne","Supprimer les irritants","Nystatine, amphotéricine, miconazole"],["Complications (strepto A, 30 %)","Abcès, otites, sinusites, pneumonies, GNA, RAA","",""]],"c":null}],"imgs":[]},{"pts":[["Angine : définition et germes responsables.","Inflammation de l'oropharynx et des amygdales palatines ; streptocoque β-hémolytique du groupe A, staphylocoque, pneumocoque, H. influenzae ; adolescents et adultes jeunes."],["Signes cliniques et paracliniques de l'angine.","Frissons, douleur et irritation de gorge, odynophagie irradiant à l'oreille (otalgie réflexe), fièvre élevée, céphalées, arthralgies, asthénie ; amygdales hypertrophiées à enduit blanchâtre (érythémato-pultacée), adénopathies sensibles et mobiles ; NFS : hyperleucocytose à PNN ; prélèvement de gorge non indispensable."],["Traitement de l'angine et sa complication la plus courante.","Pénicilline 3 à 4 millions d'unités/jour pendant 8 jours, acide acétylsalicylique, antiseptiques locaux, repos au lit ; complication la plus courante sans traitement : phlegmon péri-amygdalien."]],"tabs":[{"t":"Tableau résumé : Angine","h":["Rubrique","À retenir"],"r":[["Définition","Inflammation de l'oropharynx et des amygdales palatines ; adolescents, adultes jeunes"],["Germes","Streptocoque β-hémolytique A, staphylocoque, pneumocoque, H. influenzae"],["Signes","Frissons, fièvre élevée, odynophagie avec otalgie réflexe, arthralgies ; amygdales à enduit blanchâtre (érythémato-pultacée)"],["Biologie","Hyperleucocytose à PNN ; prélèvement de gorge non indispensable"],["Traitement","Pénicilline 3-4 MUI/j × 8 j, aspirine, antiseptiques locaux, repos"],["Complication","Phlegmon péri-amygdalien (la plus courante)"]],"c":null}],"imgs":[[145,"Aspect de l'angine (amygdales inflammatoires)"]]},{"pts":[["Définissez la dyspnée laryngée.","Bradypnée inspiratoire avec tirage sus-sternal, cornage et trouble de la voix ; toute dyspnée obstructive de l'enfant est une urgence (décompensation rapide, pronostic vital)."],["Citez des causes de dyspnée laryngée chez le nourrisson, l'enfant et l'adulte.","Nourrisson : malformation, spasmes, CE, stridor. Enfant : laryngite aiguë sous-glottique, CE méconnus, papillomatose/tumeur, traumatisme. Adulte : CE, traumatisme, laryngites, lésions nerveuses (spasmes, paralysies), tumeurs."],["Décrivez les 4 stades de la laryngite aiguë sous-glottique.","Stade 1 : calme, tirage modéré sus-sternal, TA et pouls normaux. Stade 2 : agité, tirage net sus-sternal + xiphoïdien, pouls accéléré. Stade 3 : angoissé, tirage intense + intercostal, TA élevée, cyanose. Stade 4 : inconscient, tirage et cornage absents, TA effondrée, pouls filant, rythme irrégulier, cyanose."],["Conduite à tenir devant une dyspnée laryngée.","Ne jamais faire attendre. Stades I-II : évaluer, position assise tête en hyperextension, oxygène, corticoïde IVD, aérosol d'adrénaline 1 mg dans 5 ml de NaCl 0,9 % si allergie/œdème, appeler le médecin/évacuer. Stades III-IV : intubation nasotrachéale, trachéotomie si obstacle mécanique empêchant l'intubation. Traiter la cause."]],"tabs":[{"t":"Tableau résumé : Dyspnée laryngée","h":["Rubrique","À retenir"],"r":[["Définition","Bradypnée inspiratoire + tirage sus-sternal + cornage + trouble de la voix ; urgence chez l'enfant"],["Causes nourrisson","Malformation, spasmes, CE, stridor"],["Causes enfant","Laryngite sous-glottique, CE, papillomatose, traumatisme"],["Causes adulte","CE, traumatisme, laryngites, lésions nerveuses, tumeurs"],["Stades","1 calme → 2 agité → 3 angoissé, cyanose → 4 inconscient, signes absents, TA effondrée"],["CAT","Stades I-II : assis tête en hyperextension, O2, corticoïde IVD, adrénaline aérosol ; III-IV : intubation ou trachéotomie"]],"c":null}],"imgs":[[140,"Tableau : stades de la laryngite aiguë sous-glottique"]]},{"pts":[["CE des fosses nasales : exemples, motif de consultation et CAT.","Volontaires (mousse, craie, papier, gomme, perle, maïs, haricot, arachide) ou involontaires (balle, mèche oubliée) ; obstruction nasale + rhinorrhée mucopurulente UNILATÉRALE, odeur nauséabonde ; CAT : interrogatoire, rhinoscopie ; visible : mouchage en force narine libre fermée après rétraction des cornets, extraction au crochet/pince ; invisible : évacuer."],["CE du pharynx : motif de consultation et CAT.","Arête, os, épingle ; douleur à l'arrière-gorge, dysphagie, odynophagie, au cours d'un repas ; examen avec bon éclairage et abaisse-langue ; visible : extraction à la pince ; non visible : évacuer."],["CE laryngé et trachéal : signes et traitement.","Laryngé volumineux plein : asphyxie aiguë rapidement mortelle ; moins volumineux/creux : dyspnée laryngée avec tirage, voix éteinte ; syndrome de pénétration dans la journée, sans fièvre. Trachéal : souvent mobile, quintes de toux, spasmes, dyspnée expiratoire aux changements de position. Traitement : bronchoscopie au tube rigide sous AG."],["CE de l'œsophage : signes, diagnostic et traitement.","Pièce de monnaie, arête, os, prothèse dentaire, bol alimentaire ; adulte : douleur rétrosternale, odynophagie, gêne respiratoire, dysphagie brutale (repas ou nuit : prothèse) ; enfant : troubles moindres, dysphagie sans contexte infectieux ; radio si radio-opaque ; extraction dans les 2-3 jours + ATB, antispasmodique, réhydratation parentérale."]],"tabs":[{"t":"Tableau résumé : Corps étrangers","h":["Siège","Exemples","Signes","Conduite"],"r":[["Fosses nasales","Perle, graine, papier, mèche","Rhinorrhée purulente unilatérale fétide","Mouchage forcé, crochet/pince ; invisible : évacuer"],["Pharynx","Arête, os, épingle","Douleur, dysphagie au repas","Pince si visible, sinon évacuer"],["Larynx","Objet volumineux ou creux","Asphyxie ou dyspnée, voix éteinte","Urgence"],["Trachée","CE mobile","Toux, spasmes, dyspnée positionnelle","Bronchoscopie rigide sous AG"],["Œsophage","Pièce, prothèse dentaire, bol","Dysphagie brutale, douleur rétrosternale","Radio ; extraction en 2-3 j"]],"c":null}],"imgs":[]},{"pts":[["Lavage d'oreille : définition, indications et matériel.","Mise en état de vacuité du CAE dans un but thérapeutique ; indications : bouchon de cérumen, bouchon épidermique, CE accessible ; matériel : seringue stérile 50 ml (poire à défaut), cupule stérile, compresses, coton, serviette/champ, alèze et tablier imperméables, gants stériles, réniforme."],["Décrivez la technique du lavage d'oreille.","Prévenir ; vérifier la température de l'eau sur le revers de la main ; installer et protéger cou/épaules ; préparer la solution ; le patient tient le haricot sous l'oreille ; injecter doucement puis pression modérée ; pencher la tête ; nettoyer et sécher ; contrôle otoscopique ; réinstaller ; noter (bouchon/CE, liquide, réaction)."],["Surveillance, incidents et contre-indications du lavage d'oreille.","Surveiller : efficacité, aspect du liquide, douleur, vertiges, perforation. Incidents : vertiges/nausées (eau trop froide ou trop chaude), douleur (arrêter), traumatisme (introduction trop profonde). Ne jamais laver une otorrhée de l'oreille moyenne (surinfection de la caisse) ; jamais d'eau froide, glacée ou chaude. Qualité : pavillon étiré, CAE rectiligne."]],"tabs":[{"t":"Tableau résumé : Lavage d'oreille","h":["Rubrique","À retenir"],"r":[["Définition","Mise en état de vacuité du CAE dans un but thérapeutique"],["Indications","Bouchon de cérumen, bouchon épidermique, CE accessible"],["Matériel","Seringue 50 ml, cupule, compresses, coton, alèze, gants, tablier, réniforme"],["Technique","Eau testée sur le revers de la main, injection douce puis modérée, otoscopie de contrôle"],["Incidents","Vertiges (eau trop froide/chaude), douleur → arrêter, traumatisme (seringue trop profonde)"],["Contre-indication","Jamais sur une otorrhée de l'oreille moyenne"]],"c":null}],"imgs":[]},{"pts":[["Lavage de nez : principe, indications et intérêts.","Faire passer un liquide légèrement salé dans les FN pour les nettoyer ; indications : rhinite atrophique (rhinorrhées purulentes, croûtes), encombrement nasal, après chirurgie endonasale ; intérêts : prévient/soulage les infections rhinopharyngées, bien-être respiratoire, limite les allergènes, restaure filtration-drainage-immunité, évite la descente des mucosités vers bronches, assainit le rhinopharynx, aide drainage et ventilation."],["Technique de lavage de nez chez le nourrisson de moins de 6 mois.","Mains lavées ; dosettes de SP à usage unique (pas d'eau du robinet ni minérale) ; 1) allongé sur le dos ou le côté, tête maintenue sur le côté (fausse route) ; 2) embout dans la narine du haut ; 3) presser toute la dosette en fermant la bouche ; 4) attendre la déglutition ; 5) essuyer ; recommencer de l'autre côté avec une autre dosette. Préférable au mouche-bébé. Vasoconstricteurs proscrits avant 15 ans."],["Lavage de nez chez l'enfant qui se mouche et l'adulte ; préparation de l'eau salée.","Enfant : assis, tête inclinée, embout dans la narine la plus haute, pression, se moucher fort, puis l'autre côté (sans vasoconstricteur). Adulte : position verticale, tête inclinée, narine supérieure, pression franche, laisser agir, changer de côté, moucher. Préparation : 1 L d'eau + 2 cuillères à café de gros sel (pas de sel fin de table), option bicarbonate, reposer 1 min. Fréquence : cures d'1 semaine par mois, saisonnière ou en alerte. Froid/tiède : défenses ; tiède/chaud : dilatation."]],"tabs":[{"t":"Tableau résumé : Lavage de nez","h":["Rubrique","À retenir"],"r":[["Principe","Liquide légèrement salé dans les FN pour les nettoyer"],["Indications","Rhinite atrophique, encombrement, après chirurgie endonasale"],["Nourrisson","Dosettes SP, tête sur le côté, narine du haut, bouche fermée ; pas de vasoconstricteur avant 15 ans"],["Enfant / adulte","Narine supérieure, se moucher fort ; adulte vertical, pression franche"],["Préparation","1 L d'eau + 2 c. à café de gros sel (± bicarbonate)"],["Fréquence","Cures d'1 semaine par mois, saisonnière ou en alerte"]],"c":null}],"imgs":[]},{"pts":[["Méchage antérieur : définition et indications.","Combler en accordéon les FN avec une mèche, des choanes au vestibule, pour faire l'hémostase ; indications : épistaxis, contention d'une réduction des OPN, cavoscopie, après chirurgie (cautérisation des cornets, turbinectomie, plastie)."],["Matériel et technique du méchage antérieur.","Spéculum de Palmer, pince coudée de Lubet-Barbon/Politzer, ciseaux, miroir de Clar, mèche de gaze 2-3 cm, xylocaïne 5 % naphazoline, pommade HEC… ; patient assis/demi-assis, champ, haricot sous le menton ; moucher ; xylocaïne puis attendre 5-10 min (rétracte les cornets, anesthésie) ; mèche imbibée d'hémostatique ; spéculum ; mèche introduite au fond, tassée en accordéon haut/bas ; fixation compresses + sparadrap ; ATB, antalgique, hémostatique ; déméchage à 48 h."],["Préparation psychologique et conseils de sortie après méchage.","Rassurer, acte non douloureux sous anesthésie locale, déméchage dans 48 h ; respirer par la bouche 48 h, manger et boire lentement à petites gorgées, prendre le traitement (sinon surinfection des FN), revenir en cas de nouveau saignement."]],"tabs":[{"t":"Tableau résumé : Méchage antérieur","h":["Rubrique","À retenir"],"r":[["Définition","Mèche en accordéon des choanes au vestibule pour l'hémostase"],["Indications","Épistaxis, réduction des OPN, cavoscopie, post-chirurgie"],["Matériel","Spéculum de Palmer, pince de Lubet-Barbon, mèche 2-3 cm, xylocaïne 5 % naphazoline"],["Technique","Assis, moucher, xylocaïne 5-10 min, mèche au fond en accordéon, fixation, ATB + antalgique"],["Retrait","Déméchage à 48 h"],["Conseils","Respirer par la bouche, boire lentement, prendre le traitement, revenir si saignement"]],"c":null}],"imgs":[[146,"Mèche tassée en accordéon dans la fosse nasale"]]},{"pts":[["Trachéotomie : définition et soins post-opératoires.","Ouverture de la trachée cervicale pour y introduire une canule qui court-circuite les VAS lors d'un obstacle ; soins : aspiration des sécrétions, humidification de l'air, prévention de l'infection de la plaie et broncho-pulmonaire, canule changée tous les 3 jours si possible, sonde d'aspiration dans un bocal d'eau + antiseptique (Bétadine jaune)."]],"tabs":[{"t":"Tableau résumé : Trachéotomie","h":["Rubrique","À retenir"],"r":[["Définition","Ouverture de la trachée cervicale avec canule, court-circuite les VAS"],["Soins","Aspiration, humidification, prévention infection plaie et broncho-pulmonaire"],["Canule","Changée tous les 3 jours si possible"],["Sonde d'aspiration","Bocal d'eau + antiseptique (Bétadine jaune)"],["Non développé","Indications et complications annoncées dans les objectifs"]],"c":null}],"imgs":[]}],"comp":[{"t":"Otalgie vraie vs otalgie réflexe","h":["","Otalgie vraie (otodynie)","Otalgie réflexe"],"r":[["Origine","Lésion de l'oreille","Lésion extra-auriculaire de voisinage"],["Otoscopie","Anormale (bouchon, otite, furoncle…)","Souvent normale"],["Exemples","Furoncle, OMA, bouchon, CE, zona","Carie dentaire, angine, sinusite, RGO, ATM"],["Traitement","Celui de la cause","Celui de la cause"]],"c":null},{"t":"Surdités : transmission, perception, mixte","h":["","Transmission","Perception","Mixte"],"r":[["Siège","Oreille externe ou moyenne","Oreille interne","Les deux appareils"],["Tympan","Souvent anormal","Normal","Variable"],["Causes","Bouchon, CE, otites, tumeurs, atrésie","Aminosides, presbyacousie, traumatisme sonore, congénitale","Association"]],"c":null},{"t":"Furoncle du conduit vs otite externe diffuse","h":["","Furoncle","Otite externe diffuse"],"r":[["Étendue","1/3 externe, localisé","Totalité du CAE"],["Germe / cause","Staphylocoque, grattage","Piscine, traumatisme, eczéma"],["Signe majeur","Douleur précoce intense (tragus, mastication)","Otalgie au tragus et à la traction + otorrhée fétide"],["Traitement","Antalgique, AINS, ATB générale","Nettoyage SP, gouttes ATB-corticoïde, méchage"]],"c":null},{"t":"Les 3 aspects otoscopiques de l'OMA","h":["Forme","Tympan","Conduite"],"r":[["Congestive","Rouge, épaissi, manche du marteau hypervascularisé","Traitement médical"],["Suppurée collectée","Opaque, terne, bombé","Paracentèse"],["Suppurée perforée","Pus parfois pulsatile, perforation postérieure","Traitement médical, nettoyage"]],"c":null},{"t":"Épistaxis bénigne vs grave","h":["","Bénigne","Grave"],"r":[["Abondance","Minime ou moyenne","Abondante ou répétée"],["Hémodynamique","Pas de retentissement","Perturbée (choc possible)"],["CAT","Mouchage, spray, compression 10 min, méchage si échec","Hospitalisation, TA, VVP, groupage, tamponnement ant./post."],["Médicaments","ATB (suppuration)","ATB + hémostatique parentéral"]],"c":null},{"t":"Rhinite allergique : classification","h":["","Modérée (aucun critère)","Sévère (≥ 1 critère)"],"r":[["Intermittente (< 4 j/sem ou < 4 sem/an)","Intermittente modérée","Intermittente sévère"],["Persistante (> 4 j/sem et > 4 sem/an)","Persistante modérée","Persistante sévère"],["Critères","Sommeil, activités, travail/école, symptômes invalidants","—"]],"c":null},{"t":"Sinus antérieurs vs postérieurs","h":["","Antérieurs","Postérieurs"],"r":[["Sinus","Maxillaire, frontal, ethmoïde antérieur","Ethmoïde postérieur, sphénoïdal"],["Point commun","Entourent l'orbite, drainent dans le méat moyen","—"],["Rôles (tous)","Conditionnement de l'air, ventilation, drainage","Idem"]],"c":null},{"t":"Rhinopharyngite, pharyngite aiguë, angine","h":["","Rhinopharyngite","Pharyngite aiguë","Angine"],"r":[["Siège","FN + rhinopharynx","Pharynx","Oropharynx + amygdales palatines"],["Fièvre","Brutale 39-40 °C","Modérée 38 °C","Élevée + frissons"],["Germe","Viral","Surtout viral","Strepto β-hémolytique A ++"],["Antibiotique","Inutile si non compliquée","Si bactérienne","Pénicilline 3-4 MUI/j × 8 j"]],"c":null},{"t":"Pharyngite aiguë vs chronique","h":["","Aiguë","Chronique"],"r":[["Durée","Quelques jours à 1 semaine","> 3 semaines"],["Fièvre","Modérée 38 °C","Seulement si surinfection"],["Terrain","Tout âge, surtout viral","Adulte : tabac, alcool, RGO, voix"],["Signes","Odynophagie, dysphonie, céphalées","Sécheresse, raclage, odynodysphagie"]],"c":null},{"t":"Stades de la laryngite aiguë sous-glottique","h":["","Stade 1","Stade 2","Stade 3","Stade 4"],"r":[["État","Calme","Agité","Angoissé","Inconscient"],["Tirage","Modéré, sus-sternal","Net, + xiphoïdien","Intense, + intercostal","Absent"],["Cornage","Modéré","Net","Intense","Absent"],["TA / pouls","Normaux","Normale / accéléré","Élevée / accéléré","Effondrée / filant"],["Extrémités / rythme","Normales / bradypnée insp.","Normales / bradypnée insp.","Cyanose / bradypnée","Cyanose / irrégulier"],["CAT","Assis, O2, cortico IVD","Idem ± adrénaline aérosol","Intubation","Intubation / trachéotomie"]],"c":null},{"t":"Corps étrangers selon le siège","h":["Siège","Motif / signes","Conduite"],"r":[["Fosses nasales","Rhinorrhée muco-purulente unilatérale fétide","Mouchage forcé, crochet/pince ; invisible : évacuer"],["Pharynx","Douleur arrière-gorge, dysphagie au repas","Pince si visible ; sinon évacuer"],["Larynx","Asphyxie ou dyspnée laryngée, voix éteinte","Urgence, extraction"],["Trachée","Toux et dyspnée intermittentes, posturales","Bronchoscopie rigide sous AG"],["Œsophage","Dysphagie brutale, douleur rétrosternale","Radio si opaque ; extraction en 2-3 j"],["Oreille externe","Fréquent chez l'enfant","Lavage ou crochet, pince à éviter"]],"c":null},{"t":"Lavage d'oreille vs lavage de nez vs méchage","h":["","Lavage d'oreille","Lavage de nez","Méchage antérieur"],"r":[["But","Vider le CAE","Nettoyer les FN","Hémostase"],["Indications","Bouchon cérumen/épidermique, CE accessible","Rhinite atrophique, encombrement, post-chirurgie","Épistaxis, OPN, cavoscopie, post-chirurgie"],["Matériel clé","Seringue 50 ml, haricot","Seringue 60 cc, SP, dosettes","Spéculum de Palmer, pince de Lubet-Barbon, mèche 2-3 cm"],["Piège","Jamais sur otorrhée ; eau tiède","Tête sur le côté (fausse route)","Retrait à 48 h (nécrose)"]],"c":null}]},"course":["<div class=\"pgm\">p. 3</div><h4>ANATOMIE ET PHYSIOLOGIE DE L&#x27;OREILLE</h4><p>Objectif général : reconnaître la constitution de l&#x27;oreille ainsi que son rôle.</p><p>Objectifs spécifiques : citer les différentes parties de l&#x27;oreille ; expliquer le rôle de la trompe d&#x27;Eustache ; décrire succinctement la physiologie de l&#x27;oreille externe et moyenne.</p><p>[Figure : schéma de l&#x27;oreille]</p><p><b>L&#x27;appareil auriculaire est divisé en deux : l&#x27;appareil de transmission (oreille externe et oreille moyenne) et l&#x27;appareil de perception qui constitue l&#x27;oreille interne.</b></p><h4>I- ANATOMIE</h4><h4>1-1 L&#x27;oreille externe</h4><p>Elle comprend le pavillon et le conduit auditif externe.</p><ul><li>Le pavillon : au niveau de sa face antérieure, il présente des saillies et des dépressions ; au niveau de la face postérieure, il est séparé de la mastoïde par le sillon rétro-auriculaire.</li><li>Le conduit auditif externe (méat acoustique externe) : en forme d&#x27;entonnoir, il prend fin au niveau de la couche externe du tympan. <b>Structure fibro-cartilagineuse dans son tiers (1/3) externe et osseuse dans ses deux tiers (2/3) internes.</b></li></ul><div class=\"pgm\">p. 4</div><p>Sur le tiers externe, la peau du conduit possède des <b>glandes cérumineuses</b> qui produisent le cérumen de couleur jaune, voire brune.</p><p>Le cérumen a pour rôle :</p><ul><li>de protéger les parois du conduit auditif ;</li><li>de piéger les corps étrangers (poussière, petits insectes, etc.) ;</li><li>de protéger l&#x27;oreille contre la prolifération des bactéries, éliminées grâce aux propriétés antibactériennes du cérumen ;</li><li>d&#x27;éliminer des débris de peau qui desquame.</li></ul><p>Sur les deux tiers internes du CAE, la peau adhère directement à l&#x27;os.</p><h4>1-2 L&#x27;oreille moyenne</h4><p>Creusée dans le rocher, l&#x27;oreille moyenne est constituée par une suite de cavités :</p><ul><li>la caisse du tympan qui contient la chaîne des osselets ;</li><li>la mastoïde ;</li><li>la trompe d&#x27;Eustache.</li></ul><p>Caisse du tympan : interposée entre l&#x27;oreille interne et l&#x27;oreille externe. Elle communique avec le pharynx par la trompe d&#x27;Eustache et avec la mastoïde. Elle contient les osselets : <b>marteau – enclume – étrier</b>. Ceux-ci forment avec le tympan la chaîne tympano-ossiculaire qui joue un rôle dans la transmission des vibrations sonores.</p><p>[Figure : vue otoscopique du tympan]</p><p>Trompe d&#x27;Eustache : <b>conduit ostéo-cartilagineux qui fait communiquer la caisse du tympan avec le pharynx</b> ; elle participe à l&#x27;aération de l&#x27;oreille</p><div class=\"pgm\">p. 5</div><p>moyenne et <b>sert d&#x27;équilibre de pression de part et d&#x27;autre du tympan</b>.</p><p>La mastoïde : composée de cellules aériennes creusées dans l&#x27;os temporal, dont la plus importante est l&#x27;antre mastoïdien.</p><h4>2-3 L&#x27;oreille interne ou labyrinthe</h4><p>Située dans le rocher, structure osseuse et membraneuse. Chaque partie est composée d&#x27;une unité fonctionnelle :</p><ul><li>la cochlée : <b>organe de Corti</b> ;</li><li>le vestibule : la macule ;</li><li>les canaux semi-circulaires : les crêtes ampullaires.</li></ul><h4>II- PHYSIOLOGIE</h4><h4>2-1 L&#x27;oreille externe</h4><p>Elle localise et capte les sons grâce au pavillon ; le CAE focalise, amplifie et dirige les ondes sonores vers le tympan. Sous la vibration de la membrane du tympan, le son est transmis à l&#x27;oreille moyenne.</p><h4>2-2 L&#x27;oreille moyenne</h4><p>Trois fonctions essentielles :</p><ul><li><b>transmission des ondes sonores à l&#x27;oreille interne</b> (chaîne tympano-ossiculaire, qui transforme les vibrations aériennes en vibrations de pression) ;</li><li><b>adaptation d&#x27;impédance</b> entre le milieu aérien et le milieu liquidien de l&#x27;oreille interne ;</li><li><b>protection de l&#x27;oreille interne grâce au réflexe stapédien</b>.</li></ul><h4>2-3 L&#x27;oreille interne</h4><p>Rôle dans l&#x27;audition grâce à la cochlée qui transforme le signal mécanique en signal électrique ; rôle dans l&#x27;équilibre grâce au vestibule et aux canaux semi-circulaires.</p>","<div class=\"pgm\">p. 6</div><h4>ANATOMIE ET PHYSIOLOGIE DU NEZ</h4><p>Objectif général : connaître les différentes parties du nez et des sinus.</p><p>Objectifs spécifiques : citer les différentes parois d&#x27;une fosse nasale ; nommer les groupes de sinus de la face ; citer au moins 3 fonctions du nez et des sinus.</p><h4>I- ANATOMIE DU NEZ : le nez comprend deux (2) parties</h4><h4>1-1 La pyramide nasale</h4><p>[Figure peu lisible : pyramide nasale]</p><p>Portion qui fait saillie au niveau de la partie médiane de la face, sur laquelle se greffent muscle et peau pour délimiter deux orifices symétriques.</p><p><b>Forme d&#x27;une pyramide triangulaire</b> avec une base inférieure au plan des orifices narinaires, un sommet supérieur (racine du nez) et deux faces antérolatérales. Squelette ostéo-cartilagineux recouvert en dedans par une muqueuse et en dehors par des muscles et de la peau.</p><h4>1-2 Les fosses nasales</h4><p>[Figures : fosses nasales, coupe de la région nasale]</p><p>Au nombre de 2, séparées par une <b>cloison nasale ou septum nasal</b>. On distingue :</p><div class=\"pgm\">p. 7</div><ul><li>en avant : le <b>vestibule nasal</b>, tapissé d&#x27;un épiderme garni de poils et de glandes sébacées à mucus ;</li><li>en arrière : la cavité nasale proprement dite : <b>paroi externe</b> (méats et cornets : externe, moyen, interne), <b>paroi supérieure</b> ou toit, <b>paroi inférieure</b> ou plancher, <b>paroi interne</b> = cloison nasale.</li></ul><p>La muqueuse de la cavité nasale est de deux types :</p><ul><li>muqueuse respiratoire : occupe presque toute la fosse nasale ;</li><li>muqueuse olfactive : partie supérieure de la fosse nasale, avec des éléments olfacto-sensoriels.</li></ul><p>Cloison nasale : squelette fait d&#x27;os en arrière et de cartilage en avant, essentiellement le cartilage septal dont l&#x27;altération retentit sur la morphologie du nez.</p><h4>II- PHYSIOLOGIE</h4><ul><li>Fonction olfactive : le nez est l&#x27;organe de l&#x27;odorat.</li><li>Fonction respiratoire : <b>le nez est la seule voie physiologique de la respiration</b> ; ventilation et conditionnement de l&#x27;air inspiré (réchauffement, humidification, purification).</li><li>Fonction de protection : appareil muco-ciliaire et sécrétions nasales contenant des facteurs de défense.</li><li>Fonction phonatoire : le nez influence le timbre de la voix.</li></ul>","<div class=\"pgm\">p. 8</div><h4>ANATOMIE ET PHYSIOLOGIE DES SINUS</h4><p>[Figures : sinus de la face]</p><p>Les sinus sont des cavités creusées au sein du massif facial. Deux groupes : sinus antérieurs et sinus postérieurs.</p><ul><li><b>Sinus antérieurs : sinus maxillaire, frontal et cellules ethmoïdales antérieures</b>. Points communs : ils entourent la cavité de l&#x27;orbite et <b>se drainent tous dans le méat moyen</b> (fosse nasale).</li><li><b>Sinus postérieurs : sinus ethmoïdal postérieur et sinus sphénoïdal.</b></li></ul><p>Ils jouent un rôle :</p><ul><li>dans le conditionnement de l&#x27;air intra-sinusien ;</li><li>dans la ventilation ;</li><li>dans le drainage des sécrétions.</li></ul>","<div class=\"pgm\">p. 9</div><h4>ANATOMIE ET PHYSIOLOGIE DU PHARYNX</h4><p>Objectif général : reconnaître les différentes parties du pharynx.</p><p>Objectifs spécifiques : énumérer les étages du pharynx ; décrire l&#x27;oropharynx ; citer les fonctions du pharynx.</p><h4>1-1 Définition du pharynx</h4><p><b>Conduit musculo-membraneux qui s&#x27;étend de la base du crâne au bord inférieur de la 6e vertèbre cervicale (C6)</b> (ou bord supérieur de C7) et se continue par l&#x27;œsophage.</p><p>Il mesure <b>13 cm de longueur environ</b> ; 5 cm de large en position nasale ; 4 cm en position orale ; 4 cm en position laryngée.</p><h4>1-2 Anatomie : trois étages</h4><ul><li>Tiers supérieur : <b>nasopharynx ou cavum ou rhinopharynx</b>, situé en arrière des fosses nasales et du voile du palais ; communique avec les fosses nasales par les <b>choanes</b>.</li><li>Tiers moyen : <b>oropharynx</b> (bucco-pharynx, mésopharynx), en arrière de la cavité buccale, au-dessus du larynx et de l&#x27;hypopharynx.</li></ul><p>[Figures : coupe sagittale médiane tête et cou ; cavité buccale ouverte]</p><div class=\"pgm\">p. 10</div><h4>L&#x27;oropharynx comprend :</h4><ul><li>la région amygdalienne (amygdales palatines, piliers antérieur et postérieur) ;</li><li>le voile du palais mou ;</li><li>la base de langue et les vallécules ;</li><li>les parois oropharyngées postérieure et latérale.</li><li>Tiers inférieur : <b>hypopharynx</b>, qui constitue avec le larynx le <b>carrefour aérodigestif</b> et se termine à la bouche œsophagienne.</li></ul><h4>1-3 Physiologie : fonctions fondamentales</h4><ul><li>la ventilation ;</li><li>la déglutition ;</li><li>la phonation (résonateur) ;</li><li>l&#x27;élaboration des défenses immunitaires par ses nombreuses formations lymphoïdes ;</li><li>la digestion par ses annexes : les glandes salivaires ;</li><li>le goût par les papilles linguales ;</li><li>l&#x27;audition.</li></ul>","<div class=\"pgm\">p. 11</div><h4>ANATOMIE ET PHYSIOLOGIE DU LARYNX ET DE LA TRACHÉE</h4><h4>II- Le larynx – 3-1 Anatomie</h4><p>[Figure : le larynx, vues antérieure et postérieure]</p><p>Organe du système respiratoire situé dans la gorge entre le pharynx et la trachée, constituant la partie supérieure de la trachée.</p><p>Son squelette comprend cinq principaux cartilages :</p><ul><li><b>cartilage thyroïde</b> en forme de livre ouvert en arrière, relief antérieur plus prononcé chez l&#x27;homme (pomme d&#x27;Adam) ;</li><li><b>cartilage épiglottique</b> impliqué dans la déglutition et la respiration par ouverture et fermeture du larynx ;</li><li><b>cartilages aryténoïdes</b> articulés avec le bord supérieur du cricoïde, sur lesquels s&#x27;insèrent les deux cordes vocales ; leurs mouvements déterminent la position et la tension des cordes ;</li><li><b>cartilage cricoïde</b> : base du larynx.</li></ul><p>Les cartilages sont reliés par des ligaments et entourés de membranes qui assurent la rigidité du larynx.</p><ul><li>Tenseur des cordes vocales (crico-thyroïdien) ; dilatateur de la glotte (crico-aryténoïdien latéral, selon le cours) ; ils rapprochent les cordes vocales pour la phonation.</li></ul><p>Tous ces muscles sont sous la commande des <b>nerfs récurrents droit et gauche (branches du pneumogastrique)</b> sauf le crico-</p><div class=\"pgm\">p. 12</div><p>thyroïdien, tenseur des cordes vocales, <b>innervé par le nerf laryngé supérieur</b>.</p><p>[Figure : vue de la glotte]</p><h4>3-2 Fonction du larynx</h4><ul><li>Rôle dans la <b>déglutition</b> : empêcher le passage d&#x27;aliments ou de liquides dans la trachée et les poumons ; l&#x27;épiglotte ferme le larynx et les cordes vocales se rapprochent.</li><li>Rôle <b>respiratoire</b> : laisse passer l&#x27;air (glotte ouverte).</li><li>Rôle <b>phonatoire</b> : émission et modulation des sons (glotte fermée, cordes plus ou moins tendues).</li></ul><h4>III- La trachée</h4><p>[Figure : trachée, faces antérieure et postérieure]</p><p>Définition : conduit fibro-cartilagineux qui fait suite au larynx, formé de plusieurs <b>anneaux trachéaux</b> séparés par du tissu fibro-musculaire.</p><p>Anatomie : limitée en haut par le larynx, en bas par deux orifices qui s&#x27;abouchent aux bronches souches. Tube cylindrique aplati en arrière (muscle T) ; <b>longueur de la trachée cervicale 5 à 6 cm chez l&#x27;adulte, 4 cm chez l&#x27;enfant</b>. Longueur variable selon la position de la tête et la respiration (élasticité). Le calibre est également variable :</p><div class=\"pgm\">p. 13</div><ul><li><b>6 mm chez l&#x27;enfant de 1 à 4 ans</b> ;</li><li>8 mm de 4 à 8 ans ;</li><li>10 mm de 8 à 12 ans ;</li><li><b>12 mm chez l&#x27;adulte</b>.</li></ul><h4>2-3 Physiologie</h4><p>La trachée n&#x27;est pas un tube inerte : muqueuse de type respiratoire, appareil musculaire important ; trois fonctions essentielles :</p><ul><li><b>fonction ciliaire</b> : les cils de l&#x27;épithélium assurent le drainage des sécrétions ;</li><li><b>fonction sécrétoire</b> : film fin de mucus (appelé « surfactant » dans le cours) qui protège les voies respiratoires ;</li><li><b>fonction tonique</b> : permet au larynx de monter et descendre (surtout lors de la déglutition).</li></ul>","<div class=\"pgm\">p. 14</div><h4>LES OTALGIES</h4><p>Objectif général : distinguer une otalgie vraie d&#x27;une otalgie fausse.</p><p>Objectifs spécifiques : définir l&#x27;otalgie ; énumérer les causes d&#x27;otalgie.</p><h4>I- Définition</h4><p><b>L&#x27;otalgie est une douleur de l&#x27;oreille.</b></p><ul><li><b>Primitive ou vraie</b> : liée à une lésion de l&#x27;oreille, encore appelée <b>otodynie</b>.</li><li><b>Secondaire ou fausse</b> : en rapport avec une lésion extra-auriculaire de voisinage, appelée <b>otalgie réflexe</b>.</li></ul><h4>II- Examen clinique</h4><p>D&#x27;abord l&#x27;examen de l&#x27;oreille par <b>otoscopie</b> (pavillon, CAE, tympan), puis le reste de l&#x27;examen ORL : oropharyngoscopie, rhinoscopie antérieure et postérieure. Étendu à : cavité buccale (denture, langue, gencive), oropharynx et nasopharynx, hypopharynx et larynx, articulation temporo-mandibulaire, sinus, paires crâniennes, œsophage.</p><p><b>Le traitement de l&#x27;otalgie est le traitement de sa cause.</b></p><h4>III- Étiologies</h4><h4>3-1 Otalgies primitives (otodynies, otalgies vraies) – Oreille externe</h4><ul><li>Bouchon de cérumen ou épidermique ;</li><li>corps étranger du CAE ;</li><li>infection : otite externe, furoncle du conduit, eczéma surinfecté, périchondrite du pavillon, othématome, zona.</li></ul><div class=\"pgm\">p. 15</div><ul><li>Traumatismes : plaie du conduit, fracture du conduit osseux.</li><li>Tumeurs : malignes du conduit (otalgie précoce et intense) ; bénignes.</li><li>Tympan : myringite aiguë virale ; traumatisme du tympan.</li></ul><h4>3-1-2 Oreille moyenne</h4><ul><li>Otites moyennes aiguës suppurées, barotraumatisme et leurs complications ;</li><li>otites moyennes chroniques simples ou cholestéatomateuses ;</li><li>cancers de l&#x27;oreille moyenne ; traumatismes de l&#x27;oreille moyenne.</li></ul><h4>3-2 Otalgies secondaires (réflexes, fausses)</h4><ul><li>Cavité buccale : <b>origine dentaire (caries, accidents de la dent de sagesse) avec très souvent otalgie homolatérale</b> ; glossites, stomatites ; cancers de la langue.</li><li>Oropharynx : pharyngites aiguës, amygdalites, angines ; phlegmons amygdaliens et rétro-pharyngés ; apophyses styloïdes anormalement longues ; cancers.</li><li>Larynx et hypopharynx (sinus piriforme) : cancers.</li><li>Articulation temporo-mandibulaire : arthrite, dysfonctionnement.</li><li>Sinusites aiguës ou chroniques en poussée.</li><li>Causes œsophagiennes : corps étranger, œsophagite, cancer, hernie hiatale et reflux gastro-œsophagien.</li><li>Autres : thyroïdite aiguë, lésion du rachis cervical.</li></ul>","<div class=\"pgm\">p. 16</div><h4>LES SURDITÉS</h4><p>Objectif général : être capable de prendre en charge une surdité.</p><p>Objectifs spécifiques : définir la surdité ; citer les différents types ; énumérer les causes de chaque type.</p><h4>I- Définition</h4><p><b>Trouble de l&#x27;audition sans présumer l&#x27;intensité, allant de la baisse de l&#x27;acuité auditive (hypoacousie) à la disparition totale de l&#x27;ouïe (cophose).</b></p><h4>II- Classification</h4><h4>2-1 Surdités de transmission</h4><p><b>Altération de l&#x27;oreille externe ou de l&#x27;oreille moyenne.</b></p><p>Oreille externe :</p><ul><li>bouchon de cérumen : les glandes cérumineuses du CAE sécrètent une substance jaunâtre molle ; <b>les nettoyages au coton-tige entraînent l&#x27;accumulation de cérumen qui devient noirâtre et dur</b> ;</li><li>bouchon épidermique : lamelles de desquamation de la peau du CAE ;</li><li>corps étrangers du CAE ; otites externes ; ostéomes du conduit ; tumeurs bénignes et malignes ; atrésie congénitale du conduit.</li></ul><p>Oreille moyenne :</p><ul><li>otites moyennes aiguës ; otites moyennes chroniques ;</li><li>traumatismes de l&#x27;oreille moyenne (spontanés et chirurgicaux) ; tumeurs de l&#x27;oreille moyenne.</li></ul><div class=\"pgm\">p. 17</div><h4>2-2 Surdités de perception</h4><p><b>Altération de l&#x27;oreille interne. C&#x27;est une surdité à tympan normal.</b></p><ul><li>Surdités toxiques : <b>dominées par les antibiotiques de la famille des aminosides</b> ; à redouter en cas d&#x27;association à une insuffisance rénale.</li><li><b>Presbyacousie</b> ou surdité de la sénescence : vers 50 à 60 ans.</li><li>Surdités de perception traumatiques : sonores, opératoires et accidentelles.</li><li>Surdités d&#x27;origine congénitale.</li></ul><h4>Surdités mixtes (numérotée « 2-1 » par erreur dans le cours)</h4><p>L&#x27;atteinte est au niveau des deux appareils.</p><p>Surdités congénitales ou héréditaires : évolution discrète à la naissance, s&#x27;aggravent avec le temps.</p><p><b>Symptômes à surveiller de 0 à 3 mois : absence de sursaut aux bruits forts, sommeil imperturbable, cri modifié.</b></p><h4>Points importants</h4><p>Diminution de l&#x27;acuité auditive légère, moyenne, profonde ou sévère ; groupes : transmission (oreille externe et moyenne), perception (oreille interne), mixtes (les deux).</p>","<div class=\"pgm\">p. 18</div><h4>LES ACOUPHÈNES</h4><p>Objectif général : appréhender les acouphènes.</p><p>Objectifs spécifiques : définir les acouphènes ; décrire les formes cliniques en insistant sur l&#x27;étiologie.</p><h4>1. Définition</h4><p><b>Bruits que l&#x27;on entend dans une oreille ou dans sa tête sans qu&#x27;ils aient été émis par une source extérieure ; perçus seulement par le sujet malade.</b></p><h4>2. Aspect clinique</h4><ul><li>Souvent d&#x27;origine pathologique ; permanents, intermittents ou temporaires.</li><li>Selon le son perçu : <b>tintement, chuintement, bourdonnement, sifflement</b>.</li><li>Uni- ou bilatéraux.</li></ul><h4>3. Étiologies</h4><ul><li>Surdité brusque ;</li><li>traumatisme auditif (concert, boîte de nuit, pétard) ;</li><li>traumatisme crânien ;</li><li>hypertension artérielle ;</li><li>anémie sévère et insuffisance rénale ;</li><li>stress ou dépression mentale.</li></ul><h4>4. Traitement d&#x27;urgence</h4><ul><li><b>Vasodilatateurs, corticoïdes, oxygénothérapie</b> ;</li><li>écouter de la musique pour oublier ses acouphènes ;</li><li>traitement étiologique.</li></ul>","<div class=\"pgm\">p. 24</div><h4>LES PATHOLOGIES DE L&#x27;OREILLE EXTERNE ET DE L&#x27;OREILLE MOYENNE</h4><p>Objectif général : reconnaître une affection de l&#x27;oreille externe ou moyenne et la prendre en charge.</p><p>Objectifs spécifiques : citer au moins 2 pathologies infectieuses et inflammatoires ; décrire les signes d&#x27;un furoncle du CAE, de l&#x27;otite externe diffuse et de l&#x27;OMA du nourrisson ; traiter chaque affection.</p><h4>II- Pathologies de l&#x27;oreille externe</h4><h4>2-1 Pathologies traumatiques</h4><ul><li>Plaies.</li><li><b>Othématome : collection de sang entre le périchondre et le cartilage du pavillon.</b></li><li>Corps étrangers fréquents chez l&#x27;enfant, relevant du spécialiste : <b>extraction par lavage ou au crochet, la pince est à éviter</b>.</li></ul><h4>2-2 Pathologie du cérumen</h4><p>Bouchon : cérumen mou et jaunâtre qui noircit et devient dur ; <b>extraction par lavage après instillation pendant quelques minutes d&#x27;un antiseptique moussant destiné à le ramollir</b>.</p><p>Manifestations : hypoacousie, bourdonnement, acouphènes ou vertiges ; oreille bouchée, pleine, pression ; irritation, prurit ou douleur du conduit.</p><p>Rôle du cérumen : lubrifie le CAE, freine la progression des corps étrangers vers le tympan, propriétés antimicrobiennes.</p><h4>2-3 Pathologie inflammatoire et infectieuse</h4><p>Eczéma de l&#x27;oreille : <b>prurit souvent intense</b> ; tuméfaction rouge, éruption</p><div class=\"pgm\">p. 25</div><p>vésiculeuse rarement visible ou desquamation abondante. <b>Évolue par poussées ; complication habituelle : surinfection réalisant une otite externe diffuse.</b></p><p>Traitement : nettoyage soigneux du conduit ; gouttes auriculaires antibiotique-corticoïde ; antibiotique général si surinfection ; rechercher une association mycosique.</p><h4>Le furoncle du conduit</h4><p><b>Inflammation des follicules sébacés du CAE due au staphylocoque.</b> Siège dans le <b>1/3 externe</b>, secondaire à des traumatismes discrets (allumette, épingle à cheveux, doigts sales) ou à des déficiences du terrain.</p><p>Symptomatologie :</p><ul><li><b>la douleur est le signe le plus important</b> : précoce, intense, troubles du sommeil ; à la mobilisation du pavillon, à la mastication, à la pression du tragus ;</li><li>hypoacousie par obstruction ; bourdonnements moins constants.</li></ul><p>Otoscopie : peau du CAE infiltrée ; furoncle.</p><p>[Figure : furoncle du conduit]</p><p>Traitement : antalgique, anti-inflammatoire et <b>antibiotique général (amoxicilline + acide clavulanique, oxacilline, pristinamycine)</b>.</p><h4>L&#x27;otite externe diffuse</h4><p><b>Infection du revêtement cutané du CAE</b>, déclenchée par une <b>baignade en piscine</b>, un traumatisme local, ou compliquant un eczéma. Intéresse la totalité du CAE.</p><div class=\"pgm\">p. 26</div><p>Symptomatologie :</p><ul><li><b>otalgie exacerbée par la pression du tragus et la traction du pavillon</b> ;</li><li>évolution lente : prurit, chaleur, tension, puis douleur lancinante ; <b>otorrhée d&#x27;odeur fétide</b> ; hypoacousie si conduit tuméfié et plein de débris.</li></ul><p>Examen : inflammation diffuse du CAE aux parois œdématiées (lumière diminuée) ; <b>tympan généralement normal</b>, parfois un peu rouge.</p><p>Traitement :</p><ul><li>nettoyage du CAE au sérum physiologique, aspiration si nécessaire ;</li><li><b>gouttes antibiotique-corticoïde (Panotile, Polydexa, Colicort)</b> ;</li><li><b>méchage du conduit s&#x27;il est rétréci, mèche changée quotidiennement</b> ;</li><li>antalgique per os.</li></ul><p><b>Perforation tympanique : seuls la rifamycine (Otofa) et la lincomycine (Lincocine) sont utilisables en instillation.</b></p><h4>La périchondrite aiguë</h4><p>Atteinte inflammatoire infectieuse ou traumatique du pavillon : tuméfié, rouge, puis fistule avec pus contenant le plus souvent du <b>pyocyanique</b>. Traitement : antibiotique.</p><h4>L&#x27;otomycose</h4><p><b>Otite externe fongique : dépôt blanchâtre associé à un prurit.</b> Antimycosiques locaux (Pevaryl 1 % lait ou lotion, Kétoderm crème…) pendant <b>2 à 3 semaines</b>.</p><p>Les malformations de l&#x27;oreille externe sont de gravité variable :</p>","<div class=\"pgm\">p. 27</div><ul><li>une oreille décollée.</li></ul><h4>III- Pathologies de l&#x27;oreille moyenne</h4><p>Atteintes infectieuses, inflammatoires, traumatiques ou malformatives.</p><h4>3-1 Les otites moyennes aiguës du nourrisson</h4><p>Définition : <b>inflammation de la muqueuse des cavités de l&#x27;oreille moyenne évoluant sur moins de trois semaines.</b> Les OMA microbiennes constituent la majorité des otites de l&#x27;enfant. <b>Elle survient la plupart du temps au décours d&#x27;une rhinopharyngite.</b></p><p>Germes : <b>Haemophilus influenzae, Streptococcus pneumoniae, Moraxella catarrhalis, mais le plus souvent virale.</b></p><p>Signes cliniques : fièvre, diarrhée, pleurs inexpliqués, vomissements, rhinite aiguë, <b>porte le doigt à l&#x27;oreille</b>.</p><p><b>Le diagnostic repose sur l&#x27;otoscopie.</b> Le CAE doit être bien nettoyé sans traumatisme.</p><p>[Figures : aspects du tympan]</p><ul><li><b>Otite congestive</b> : tympan rouge et épaissi, hypervascularisation du manche du marteau.</li><li><b>OMA suppurée collectée</b> : tympan opaque, terne, <b>bombé</b> ; reliefs du manche du marteau peu visibles.</li><li><b>OMA suppurée perforée</b> : le pus s&#x27;écoule, parfois de façon pulsatile, par une perforation ponctiforme ou linéaire postérieure.</li></ul><div class=\"pgm\">p. 28</div><p><b>Chez le nourrisson, les otites sont bilatérales dans plus de la moitié des cas.</b></p><p>Faire un examen digestif à la recherche du pli cutané de déshydratation.</p><p>Diagnostic différentiel : otite externe, otite séromuqueuse, otite moyenne chronique.</p><p>Évolution : bien traitée, favorable (apyrexie, s&#x27;alimente, prend du poids).</p><p>Complications :</p><ul><li>OMA récidivantes : <b>si hypertrophie des végétations adénoïdes, adénoïdectomie</b> ;</li><li>mastoïdites aiguës ; paralysies faciales otitiques ; méningite.</li></ul><h4>Conduite à tenir</h4><ul><li>Désobstruction nasale par un vasoconstricteur <b>de moins de 5 jours</b> ;</li><li>désinfection rhinopharyngée par solution physiologique ;</li><li><b>antibiotique (amoxicilline + acide clavulanique) 80 à 100 mg/kg/jour</b> ;</li><li><b>Célestine solution 10 gouttes/kg/jour</b> ;</li><li><b>paracentèse au stade suppuré collecté</b> ;</li><li>prévention : limiter les infections naso-sinusiennes (hygiène nasale, sérum physiologique, mouchage) ; rechercher et traiter les allergies respiratoires et alimentaires ; <b>vaccination contre le pneumocoque et l&#x27;Haemophilus influenzae</b>.</li></ul>","<div class=\"pgm\">p. 19</div><h4>LES ÉPISTAXIS</h4><p>Objectif général : apprécier le type d&#x27;épistaxis pour une prise en charge.</p><p>Objectifs spécifiques : définir l&#x27;épistaxis ; citer au moins cinq causes ; énumérer la CAT devant une épistaxis bénigne ; indiquer l&#x27;attitude devant une épistaxis grave.</p><h4>I- Définition</h4><p><b>Saignement d&#x27;origine endonasale</b>, tantôt antérieur extériorisé par la narine, tantôt postérieur extériorisé dans le rhinopharynx, ou mixte. <b>C&#x27;est une urgence fréquente.</b></p><p><b>Dans 90 % des cas, il provient de la tache vasculaire (Kisselbach, zone sur-vascularisée) sur la cloison nasale, à un centimètre environ de l&#x27;entrée narinaire.</b></p><p>Épistaxis bénigne : saignement minime ou moyen. Épistaxis grave : par son abondance ou sa répétition, avec perturbation hémodynamique.</p><h4>II- Causes</h4><h4>2-1 L&#x27;hypertension artérielle</h4><p><b>Prendre la TA chez tout malade adulte ayant une épistaxis.</b></p><h4>2-2 Causes traumatiques</h4><p>Fracture des os propres du nez ; traumatisme de la face (disjonction crânio-faciale) ; après chirurgie (rhinoseptoplastie, septoplastie, polypectomie).</p><h4>2-3 Maladies hémorragiques</h4><p>Maladie de Rendu-Osler (angiomatose hémorragique familiale) ; thrombopénies, thrombopathies, leucoses, aplasies ; hémophilie, insuffisance hépatique, fibrinolyses, CIVD ; patients sous anticoagulants ; insuffisance rénale.</p><div class=\"pgm\">p. 20</div><h4>2-4 Causes tumorales</h4><p>Bénignes : angiofibromes de l&#x27;ethmoïde et de la cloison ; <b>l&#x27;angiofibrome juvénile est une tumeur de l&#x27;adolescent de sexe masculin très hémorragique (fibrome nasopharyngien)</b>.</p><p>Malignes : tumeurs malignes des fosses nasales, des sinus, du cavum ; tumeurs nerveuses des fosses nasales.</p><h4>2-5 Causes infectieuses et inflammatoires</h4><p>Enfant : rhinopharyngites aiguës, rhinosinusites à répétition. Adulte : sinusites aiguës ou chroniques, rhinites allergiques. Typhoïde ; grippe.</p><h4>2-6 Autres causes</h4><p>Corps étrangers chez l&#x27;enfant ; perforation septale avec croûte ; grossesse.</p><h4>III- Conduite à tenir</h4><h4>3-1 Épistaxis bénigne (faible abondance, sans retentissement hémodynamique)</h4><ul><li>Mouchage des caillots et pulvérisation de <b>lidocaïne 5 % à la naphazoline</b> ;</li><li>examen complet des fosses nasales : origine du saignement sur la cloison antérieure ;</li><li><b>compression bidigitale des ailes du nez pendant 10 minutes, tête penchée en avant</b>, après mise en place d&#x27;un tampon de coton imbibé d&#x27;eau oxygénée ou de thrombase ;</li><li>en cas d&#x27;échec : <b>méchage ou tamponnement antérieur</b>, mèche grasse placée en accordéon dans les deux fosses nasales ;</li><li><b>mèche enlevée au plus tard 48 h après pour prévenir tout risque de nécrose septale.</b></li></ul><div class=\"pgm\">p. 21</div><ul><li>Couverture antibiotique pour éviter une suppuration.</li><li>Une fois le tamponnement effectué, vérifier par le pharynx l&#x27;arrêt total du saignement.</li><li>En cas de nouvel échec ou de succès incomplet : bilan sanguin et examen en milieu spécialisé ORL.</li></ul><h4>3-2 Épistaxis de moyenne ou de grande abondance</h4><p><b>Hospitalisation</b>, prise en urgence de la <b>TA</b>, <b>voie veineuse</b> pour corriger un éventuel choc, <b>groupage</b> pour une éventuelle transfusion, <b>tamponnement antérieur voire postérieur</b>, avec couverture antibiotique et hémostatique par voie parentérale.</p><p>(Moitié inférieure de la page blanche.)</p>","<div class=\"pgm\">p. 29</div><h4>LES RHINITES</h4><p>Objectif général : assurer la liberté des fosses nasales.</p><p>Objectifs spécifiques : décrire les signes cliniques d&#x27;une rhinite allergique ; citer au moins trois causes de rhinite.</p><h4>I- Définition</h4><p><b>Les rhinites sont des inflammations des fosses nasales.</b> L&#x27;interrogatoire (durée, caractère infectieux, épidémique, facteurs déclenchants, périodicité, uni- ou bilatéralité) et l&#x27;examen de la cavité nasale (septum, polypes, œdème, sécrétions séreuses ou purulentes) permettent la classification.</p><h4>II- Classification</h4><h4>2-1 Rhinites allergiques</h4><p><b>Triade brutale : obstruction nasale, éternuements en salve, rhinorrhée aqueuse.</b></p><ul><li><b>Intermittentes : moins de 4 jours par semaine ou moins de 4 semaines consécutives par an.</b></li><li><b>Persistantes : plus de 4 jours par semaine et plus de 4 semaines dans l&#x27;année.</b></li></ul><p>Chacune est divisée en deux groupes selon l&#x27;intensité de la gêne.</p><div class=\"pgm\">p. 30</div><p><b>Formes modérées</b> : le patient ne présente aucun des symptômes suivants : troubles du sommeil ; diminution des activités quotidiennes, de loisirs ou sportives ; diminution de l&#x27;activité professionnelle ou scolaire ; symptômes invalidants.</p><p><b>Formes sévères</b> : au moins un de ces symptômes.</p><p>Soit 4 formes : intermittente modérée, intermittente sévère, persistante modérée, persistante sévère.</p><h4>2-2 Pathologies infectieuses</h4><p>Virales, bactériennes, mycosiques, parasitaires : <b>aiguës si symptômes &lt; 12 semaines, chroniques au-delà de 12 semaines</b>.</p><h4>2-4 Rhinites médicamenteuses (pas de « 2-3 » dans le cours)</h4><p>Aspirine, réserpine, guanéthidine, inhibiteurs de l&#x27;enzyme de conversion. <b>Les vasoconstricteurs au long cours et à forte dose retentissent sur la vasomotricité de la muqueuse nasale.</b></p><h4>2-5 Rhinites des troubles endocriniens</h4><p>Hyperthyroïdie, acromégalie ; <b>3e trimestre de la grossesse</b> (œstrogènes les plus élevés).</p><h4>2-6 Rhinites inflammatoires non allergiques</h4><p><b>Éosinophiles &gt; 20 % dans les sécrétions et enquête allergique négative : NARES</b> (rhinite non allergique à éosinophiles).</p><div class=\"pgm\">p. 31</div><p>Il y a aussi les anomalies induites par des produits chimiques ou des conditions climatiques ou environnementales.</p><h4>2-7 Rhinites idiopathiques (étiologie non encore précisée)</h4><h4>Traitement</h4><ul><li>libérer les fosses nasales par mouchage ;</li><li><b>vasoconstricteur de courte durée</b> ;</li><li>lavage nasal pour désinfecter ;</li><li><b>antihistaminique</b> contre l&#x27;allergie ;</li><li><b>éviction de l&#x27;allergène</b> ;</li><li>lutter contre les symptômes invalidants.</li></ul><p>(Moitié inférieure de la page blanche.)</p>","<div class=\"pgm\">p. 32</div><h4>LES SINUSITES AIGUËS</h4><p>Objectifs spécifiques : décrire le tableau clinique d&#x27;une sinusite maxillaire aiguë ; donner son traitement.</p><h4>Définition</h4><p><b>Atteinte infectieuse de la muqueuse des sinus de la face dont la durée d&#x27;évolution est de moins de trois semaines.</b> Au cours d&#x27;une rhinite, d&#x27;un épisode grippal, parfois après un bain en piscine.</p><p>Germes : Haemophilus influenzae, S. pneumoniae, S. aureus, anaérobies.</p><h4>1-1 La sinusite maxillaire aiguë</h4><p><b>La plus fréquente</b>, souvent secondaire à un coryza, une infection virale des VAS ou un bain. Germes : H. influenzae, pneumocoque, staphylocoque doré. <b>Habituellement unilatérale</b> ; si tous les sinus homolatéraux sont atteints : <b>pansinusite aiguë</b>.</p><p>Tableau caractéristique :</p><ul><li><b>douleur faciale unilatérale, sous-orbitaire, pulsatile, augmentée par la position penchée en avant et la toux</b> ;</li><li>céphalée diffuse ; obstruction nasale ;</li><li>rhinorrhée purulente parfois striée de sang du côté de la douleur ;</li><li><b>cacosmie</b> subjective ; <b>anosmie</b>.</li></ul><p>Examen après rétraction de la muqueuse : <b>pus au niveau du méat moyen</b> ; muqueuse inflammatoire, cornets tuméfiés ; douleur à la pression du nerf sous-orbitaire.</p><div class=\"pgm\">p. 33</div><p><b>La radiographie en incidence de Blondeau montre une opacité constante du sinus maxillaire.</b></p><h4>Traitement</h4><ul><li>décongestionner les ostiums (lavage du nez) ;</li><li>antalgiques ;</li><li><b>antibiothérapie générale pendant 10 jours</b> : amoxicilline-acide clavulanique, C3G (Orelox, Texodil) ou pristinamycine (Pyostacine) ;</li><li><b>corticothérapie en cure courte de 5 jours à 0,5–1 mg/kg/j (Cortancyl)</b> ;</li><li>soins locaux : lavage au sérum physiologique ; antibiotique, anti-inflammatoire et antalgique en aérosol sonique ;</li><li>antihistaminique <b>après</b> le traitement antibiotique.</li></ul><p><b>Ce traitement bien conduit évitera le passage à la chronicité.</b></p>","<div class=\"pgm\">p. 34</div><h4>LES VÉGÉTATIONS ADÉNOÏDES</h4><p>Objectifs spécifiques : énumérer les signes cliniques ; citer au moins trois complications.</p><h4>I- Définition</h4><p><b>Hypertrophie du tissu lymphoïde de la paroi postéro-supérieure du rhinopharynx due aux infections respiratoires répétées : hypertrophie de l&#x27;amygdale pharyngée de Luschka.</b></p><h4>2-1 Signes cliniques</h4><p><b>Obstruction nasale bilatérale</b> entraînant : respiration buccale ; ronflement nocturne ; troubles du sommeil.</p><p><b>Rhinorrhée muco-purulente = surinfection adénoïdienne.</b></p><h4>2-2 Examen clinique</h4><p>En obstruant fermement la bouche du nourrisson, on teste la perméabilité nasale : des végétations obstructives rendent la respiration nasale impossible. Mucopus sur la paroi postérieure du pharynx = infection adénoïdienne.</p><h4>2-3 Signes radiologiques</h4><p><b>Cliché de profil du cavum en inspiration et bouche fermée</b> : l&#x27;espace clair normal entre les végétations et le voile du palais est comblé.</p><h4>III- Complications</h4><p>3-1 Tubotympaniques : <b>otites moyennes aiguës récidivantes</b> ; otites séro-muqueuses.</p><div class=\"pgm\">p. 35</div><p>3-2 Laryngo-trachéo-bronchiques : laryngites aiguës sous-glottiques à répétition ; trachéites récidivantes (toux sèche) ; bronchopneumopathies récidivantes traînantes.</p><p>3-3 Rhinosinusiennes : rhinosinusites récidivantes ; <b>ethmoïdite aiguë</b> ; adénites cervicales aiguës ; détresse respiratoire aiguë du nouveau-né et du nourrisson.</p><h4>IV- Traitement</h4><p><b>Adénoïdectomie si rhonchopathie invalidante avec apnée du sommeil.</b></p><p>(Numéro de page imprimé illisible ; moitié inférieure blanche.)</p>","<div class=\"pgm\">p. 1</div><h4>LES RHINOPHARYNGITES</h4><p>Objectif général : soigner une rhinopharyngite non compliquée.</p><p>Objectifs spécifiques : énumérer les signes cliniques ; décrire l&#x27;examen clinique ; donner la CAT ; citer au moins trois complications.</p><h4>I- Définition</h4><p><b>Les rhinopharyngites aiguës de l&#x27;enfant sont les plus fréquentes. Inflammation aiguë de la muqueuse des fosses nasales et du rhinopharynx, le plus souvent d&#x27;origine virale.</b></p><h4>2-1 Signes de début</h4><ul><li><b>Fièvre brutale souvent élevée (39 à 40 °C)</b> ; irritabilité, agitation ; parfois vomissements ou diarrhée ; adénopathies cervicales bilatérales.</li><li>Signes rhinologiques : <b>obstruction nasale bilatérale</b> ; rhinorrhée d&#x27;abord séreuse puis muco-purulente bilatérale ; éternuements.</li><li>Signes oculaires fréquents : rougeur conjonctivale, larmoiement, sécrétion purulente à l&#x27;angle interne.</li><li>Signes laryngo-trachéaux : toux d&#x27;irritation rauque ; cri modifié.</li></ul><h4>2-2 Examen clinique</h4><p>Rhinoscopie : muqueuse nasale très rouge ; obstruction par du <b>mucopus</b> (mucus jaunâtre contenant polynucléaires et macrophages).</p><div class=\"pgm\">p. 2</div><p>Oropharyngoscopie : muqueuse très rouge surtout au niveau des piliers du voile et des amygdales. <b>Otoscopie : congestion de la membrane tympanique.</b></p><h4>III- Traitement</h4><p>Soins locaux : <b>désinfection rhinopharyngée pluriquotidienne au sérum physiologique</b> ; aspiration des sécrétions (mouche-bébé) ; grand enfant : éducation au mouchage, lutter contre le reniflement.</p><p>Soins généraux : acide acétylsalicylique 80 mg/kg/jour (anti-inflammatoire, antipyrétique, antalgique) [notion datée : l&#x27;aspirine est aujourd&#x27;hui évitée chez l&#x27;enfant].</p><p><b>Dans une rhinopharyngite non compliquée, l&#x27;antibiothérapie est inutile.</b></p><h4>IV- Évolution</h4><p><b>Guérison complète habituellement en 5 jours.</b> Surveillance régulière pour dépister une complication :</p><ul><li><b>otite moyenne aiguë, la plus fréquente</b> ;</li><li>laryngite aiguë sus-glottique ou trachéo-bronchites ;</li><li>adénophlegmon du cou ou phlegmon rétro-pharyngé ;</li><li>sinusite maxillaire, ethmoïdite aiguë.</li></ul><p>Traitement (en cas de complication) : désinfection au sérum physiologique ; anti-inflammatoire et <b>antibiotique (amoxicilline, amoxicilline + acide clavulanique) pendant 8 jours</b> ; contrôle une semaine après.</p>","<div class=\"pgm\">p. 3</div><h4>LES PHARYNGITES</h4><p>(Chapitre absent du sommaire imprimé.)</p><p>Définition : <b>inflammation de la gorge ou du pharynx liée à une bactérie type streptococcique, à un virus ou à une cause fongique.</b> Affection bénigne la plupart du temps ; peut atteindre fosses nasales, amygdales. Types : aiguë, chronique.</p><p><b>Pharyngite aiguë : dure de quelques jours à une semaine ; d&#x27;origine infectieuse surtout virale.</b></p><p>Symptômes :</p><ul><li><b>odynophagie</b> (douleur à la déglutition) ; <b>dysphonie</b> (enrouement) ;</li><li>fièvre modérée à 38 °C ; parfois céphalées, asthénie ; ganglions cervicaux ; toux parfois persistante ;</li><li>rhinite associée (obstruction, rhinorrhée muco-purulente) : on parle de rhinopharyngite.</li></ul><p>Causes de la rhinopharyngite : presque toutes infectieuses, <b>virales dans 90 % des cas</b> ; traitement symptomatique ; <b>antibiotiques inutiles et déconseillés (résistance)</b>.</p><p>Oropharyngoscopie : inflammation ; un <b>TROD (test rapide d&#x27;orientation diagnostique)</b> détermine le germe.</p><p>Facteurs de risque : cigarette ou fumée du tabac ; alcool en excès ;</p><div class=\"pgm\">p. 4</div><p>facteurs environnementaux (poussière, air trop sec ou trop froid, climatisation, gouttes nasales répétées).</p><h4>La pharyngite chronique</h4><p><b>S&#x27;installe progressivement et dure plus de trois semaines</b> ; symptômes moins marqués, localisés à la gorge ; <b>fièvre seulement en cas de surinfection</b>.</p><ul><li>sécheresse constante de la gorge ; raclage ; douleur pharyngée ;</li><li><b>odynodysphagie</b> : difficulté douloureuse à avaler salive, nourriture ou liquide.</li></ul><p>Causes : <b>plus fréquente chez l&#x27;adulte</b> : tabagisme actif et passif, alcool, environnement, rhinite, rhinosinusite chronique, RGO, métier d&#x27;enseignant, de chanteur.</p><p>Diagnostic : interrogatoire ; oropharyngoscopie ; palpation cervicale (adénopathies) ; prélèvement de gorge (germe bactérien, viral ou mycosique).</p><p>Évolution : <b>provoquée par une bactérie dans 30 % des cas : le streptocoque bêta-hémolytique du groupe A</b>. Complications :</p><ul><li>abcès péri-pharyngé ; otites moyennes ; sinusites ;</li></ul><div class=\"pgm\">p. 5</div><ul><li>laryngites ; trachéo-bronchites ; pneumonies ;</li><li><b>glomérulonéphrite aiguë post-streptococcique</b> ;</li><li><b>rhumatisme articulaire aigu</b>.</li></ul><p>Traitement : lavage de nez et mouchage ; boissons chaudes ; sprays, paracétamol ou antipyrétique ; <b>antibiotiques si origine bactérienne</b>.</p><h4>La pharyngite mycosique</h4><p>Sensations de brûlures ou de coton dans la bouche, dysphagies, parfois agueusie, sécheresse buccale, petits saignements. <b>Plaques blanc crème à l&#x27;examen.</b></p><p>Traitement : antifongiques : <b>nystatine (Mycostatine) en comprimé à sucer</b>, amphotéricine (Fungizone) ou miconazole (Daktarin) en gel.</p><p>(Moitié inférieure de la page blanche.)</p>","<div class=\"pgm\">p. 6</div><h4>LES ANGINES OU AMYGDALITES AIGUËS</h4><p>Objectif général : prendre en charge une angine.</p><p>Objectifs spécifiques : énumérer les germes ; décrire les signes cliniques et paracliniques ; citer 3 complications.</p><h4>I- Définition</h4><p><b>Inflammation de l&#x27;oropharynx et des amygdales palatines.</b></p><h4>II- Étiopathogénie</h4><p><b>Streptocoque bêta-hémolytique du groupe A</b> (écrit « B hémolytique » dans le cours), staphylocoque, pneumocoque, Haemophilus influenzae. <b>Surtout les adolescents et les adultes jeunes.</b></p><h4>III- Signes cliniques</h4><ul><li>frissons ; irritation de la gorge ; douleur pharyngée ;</li><li><b>odynophagie irradiant vers l&#x27;oreille : otalgie réflexe</b> ;</li><li>fièvre élevée, céphalées, douleurs articulaires, asthénie.</li></ul><p>Examen ORL : <b>amygdales hypertrophiées recouvertes d&#x27;un enduit blanchâtre : angine érythémato-pultacée</b>. Adénopathies cervicales sensibles et mobiles.</p><p><b>Sans traitement : phlegmon péri-amygdalien, complication la plus courante.</b></p><div class=\"pgm\">p. 7</div><p>[Figure : aspect de l&#x27;angine]</p><h4>IV- Signes biologiques</h4><ul><li>NFS : <b>hyperleucocytose à polynucléaires</b>.</li><li>Prélèvement de gorge pour identifier le germe (streptocoque bêta-hémolytique du groupe A) mais <b>pas indispensable</b>.</li></ul><h4>V- Traitement</h4><ul><li><b>Pénicillinothérapie : 3 à 4 millions d&#x27;unités par jour pendant 8 jours</b> ;</li><li>acide acétylsalicylique ;</li><li>antiseptiques locaux pharyngés ;</li><li>repos au lit.</li></ul>","<div class=\"pgm\">p. 22</div><h4>LA DYSPNÉE LARYNGÉE</h4><p>Objectif général : reconnaître une dyspnée laryngée.</p><p>Objectifs spécifiques : définir la D.L ; citer au moins deux causes chez le nourrisson, l&#x27;enfant et l&#x27;adulte ; décrire les stades d&#x27;évolution de la laryngite aiguë sous-glottique.</p><h4>Définition</h4><p><b>Bradypnée inspiratoire avec tirage sus-sternal, cornage et trouble de la voix.</b> <b>Toute dyspnée obstructive de l&#x27;enfant est une urgence</b> car elle peut se décompenser rapidement et mettre en jeu le pronostic vital. Un examen clinique méthodique apprécie la gravité et l&#x27;étiologie probable.</p><h4>Causes</h4><p>Chez le nourrisson :</p><ul><li>malformation ; spasmes (contraction involontaire des muscles lisses) ; corps étrangers ;</li><li><b>stridor</b> : affection bénigne du nouveau-né, inspiration bruyante aiguë sans gêne respiratoire ni cyanose.</li></ul><p>Chez l&#x27;enfant :</p><ul><li><b>laryngites aiguës sous-glottiques</b> ; corps étrangers méconnus ; papillomatose ou autre tumeur ; traumatisme.</li></ul><p>Chez l&#x27;adulte :</p><ul><li>corps étrangers ; traumatisme ; laryngites diverses ; lésions nerveuses (spasmes et paralysies) ; tumeurs bénignes et malignes.</li></ul><div class=\"pgm\">p. 23</div><h4>Classification des laryngites aiguës sous-glottiques en 4 stades de gravité croissante</h4><p>[Tableau : stades 1 à 4]</p><ul><li>État de l&#x27;enfant : calme / agité / angoissé / <b>inconscient</b>.</li><li>Tirage : modéré / net / intense / <b>absent</b> ; type : sus-sternal / sus-sternal + xiphoïdien / + intercostal.</li><li>Cornage : modéré / net / intense / absent.</li><li>TA : normale / normale / élevée / <b>effondrée</b>. Pouls : normal / accéléré / accéléré / <b>filant</b>.</li><li>Extrémités : normales / normales / cyanose / cyanose. Rythme : bradypnée inspiratoire (stades 1-3) / <b>irrégulier</b> (stade 4).</li></ul><h4>C.A.T</h4><p><b>Il ne faut jamais faire attendre un client atteint de dyspnée laryngée.</b></p><p>Stades I et II :</p><ul><li>évaluer les signes décrits plus haut ;</li><li><b>maintien en position assise, tête en hyperextension</b> ;</li><li>oxygénation ; <b>corticoïde en IVD</b> ;</li><li>allergie ou œdème : <b>1 mg d&#x27;adrénaline dans 5 ml de NaCl 0,9 % en aérosol</b> ;</li><li>appeler le médecin ou évacuer le patient.</li></ul><p>Stades III et IV :</p><ul><li><b>intubation nasotrachéale</b> ;</li><li><b>trachéotomie lorsqu&#x27;il s&#x27;agit d&#x27;un obstacle mécanique interdisant l&#x27;intubation</b>.</li></ul><p>Dans tous les cas, traiter la cause.</p>","<div class=\"pgm\">p. 8</div><h4>LES CORPS ÉTRANGERS DES VOIES AÉRO-DIGESTIVES</h4><p>Objectif général : reconnaître un corps étranger dans la sphère ORL.</p><p>Objectifs spécifiques : citer au moins trois CE ; indiquer le motif de consultation de chaque voie ; décrire la CAT.</p><p>Introduction : orifices de la face fréquemment siège de pénétrations. <b>Accident relativement fréquent chez l&#x27;enfant, à l&#x27;évolution parfois catastrophique</b> (tendance à porter à la bouche). Chez l&#x27;adulte : surtout CE alimentaires (arête, os) et bol alimentaire trop gros et mal mastiqué.</p><h4>I- Définition</h4><p><b>Présence d&#x27;un objet ou d&#x27;un être vivant dans un endroit inhabituel.</b></p><h4>2-1 CE des fosses nasales</h4><p>Volontaires : mousse de matelas, craie, boulette de papier, gomme, perle, maïs, haricot, arachide… Involontaires : balle, <b>mèche oubliée</b>.</p><p>Motif de consultation : <b>obstruction nasale avec rhinorrhée muco-purulente UNILATÉRALE</b> ; odeur nauséabonde ; découverte d&#x27;un objet.</p><p>CAT : interrogatoire (caractéristiques et existence réelle du CE) ;</p><div class=\"pgm\">p. 9</div><p>rhinoscopie :</p><ul><li>CE visible : <b>mouchage en force en fermant la narine libre, après rétraction des cornets</b> ; extraction au crochet ou à la pince ;</li><li>CE invisible : évacuer le malade.</li></ul><h4>2-2 CE du pharynx</h4><p>Arête, os, épingle… Motif : douleur à l&#x27;arrière-gorge, dysphagie, odynophagie, <b>au cours d&#x27;un repas</b> pour les CE alimentaires.</p><p>Examen : bon éclairage et abaisse-langue. <b>Visible : extraire à la pince ; non visible : évacuer.</b></p><h4>2-3 CE laryngés et trachéaux</h4><p>CE laryngé :</p><ul><li><b>volumineux et plein : asphyxie aiguë rapidement mortelle</b> ;</li><li>moins volumineux ou creux : enclavé, dyspnée laryngée avec tirage, voix souvent éteinte ;</li><li><b>y penser devant un syndrome de pénétration survenu dans la journée et sans fièvre</b> (élimine une laryngite aiguë).</li></ul><p>CE trachéal : <b>souvent mobile</b> ; troubles respiratoires intermittents : quintes de toux,</p><div class=\"pgm\">p. 10</div><p>accès de spasmes laryngés ou de dyspnée expiratoire lors des changements de position.</p><p>Traitement : <b>extraction par bronchoscopie au tube rigide avec optiques sous anesthésie générale</b>.</p><h4>2-4 CE de l&#x27;œsophage</h4><p>Pièce de monnaie, arête, os, prothèses dentaires, bol alimentaire trop volumineux et mal mastiqué.</p><p>Tableau clinique selon l&#x27;âge :</p><ul><li>Adulte : douleur rétrosternale, odynophagie, gêne respiratoire, <b>dysphagie d&#x27;apparition brutale</b> au cours d&#x27;un repas (CE alimentaire) ou de la nuit (<b>prothèse dentaire</b>).</li><li>Enfant : troubles moins marqués ; dysphagie sans contexte infectieux.</li></ul><p>Diagnostic (numéroté « 3-4-2 ») : <b>la radiologie montre le CE s&#x27;il est radio-opaque</b>.</p><p>Traitement : <b>seul traitement : l&#x27;extraction dans les 2-3 jours</b>, sous couverture antibiotique, antispasmodique, réhydratation parentérale (formulation ambiguë « sans couverture » dans le cours).</p>","<div class=\"pgm\">p. 11</div><h4>LAVAGE D&#x27;OREILLE</h4><p>Objectif général : maîtriser la technique.</p><p>Objectifs spécifiques : définir ; citer les indications ; citer le matériel ; décrire la technique et les incidents.</p><h4>1. Définition</h4><p><b>Mise en état de vacuité du conduit auditif externe dans un but thérapeutique.</b></p><h4>2. Indications</h4><ul><li><b>bouchon de cérumen</b> ; <b>bouchon épidermique</b> ; <b>corps étranger accessible</b>.</li></ul><h4>3. Matériel</h4><p><b>Seringue stérile (50 ml)</b>, poire à lavage à défaut, cupule stérile, compresses, coton, serviette ou champ, alèze imperméable, gants stériles, tablier imperméable, réniforme.</p><h4>4. Technique</h4><ul><li>prévenir le patient ;</li><li><b>vérifier la température de l&#x27;eau en la versant sur le revers de la main</b> ;</li><li>installer confortablement ; protection autour du cou et sur les épaules ;</li><li>préparer la solution dans la cupule stérile ;</li></ul><div class=\"pgm\">p. 12</div><ul><li>prélever la solution ; <b>le patient maintient le haricot sous l&#x27;oreille</b> ;</li><li><b>injecter doucement pour ne pas surprendre, puis augmenter la pression qui doit rester modérée</b> ;</li><li>pencher la tête pour l&#x27;écoulement ; nettoyer et sécher l&#x27;oreille ;</li><li><b>contrôler la vacuité du CAE par otoscopie</b> ; réinstaller ;</li><li>noter bouchon/CE, aspect du liquide, réaction du patient.</li></ul><h4>5. Surveillance</h4><p>Efficacité (CE ou bouchon dans le liquide) ; aspect du liquide ; douleur, vertiges ; perforation tympanique.</p><h4>6. Critères de qualité</h4><p>Maintien correct du nourrisson/enfant ; <b>étirement correct du pavillon : CAE rectiligne</b> ; extraction du CE ou du bouchon ; absence de vertiges et nausées.</p><h4>7. Prévention des risques</h4><p>Lavage des mains avant et après au savon doux ; lavage antiseptique en présence d&#x27;infection.</p><h4>8. Incidents et accidents</h4><ul><li><b>vertiges et nausées : eau trop froide ou trop chaude</b> ;</li><li><b>douleur : arrêter le lavage</b> ;</li><li><b>traumatisme : introduction trop profonde de la seringue</b>.</li></ul><div class=\"pgm\">p. 13</div><h4>9. Conseils pratiques</h4><ul><li><b>Ne jamais faire de lavage dans une otorrhée de l&#x27;oreille moyenne</b> : risque de surinfecter la caisse du tympan avec l&#x27;eau et les débris souillés du CAE.</li><li><b>Ne jamais laver avec de l&#x27;eau froide, glacée ou chaude.</b></li></ul><h4>LE LAVAGE DE NEZ</h4><p>Objectifs : citer les indications, les intérêts ; décrire la technique.</p><p>Principe : <b>faire passer un liquide légèrement salé (eau ou sérum physiologique) dans les fosses nasales pour les nettoyer et en évacuer les impuretés</b>, à la pipette (sérum du commerce) ou à la seringue.</p><h4>II- Indications</h4><ul><li><b>rhinite atrophique avec rhinorrhées purulentes et croûtes</b> ; encombrement nasal ; <b>après chirurgie endonasale</b>.</li></ul><h4>III- But</h4><p>Dégager le nez (respiration libre).</p><h4>III- Intérêts</h4><ul><li>prévient et soulage les symptômes des infections rhinopharyngées ;</li><li>améliore le bien-être respiratoire (élimine les particules) ;</li><li>limite le dépôt des allergènes ;</li><li>restaure l&#x27;activité physiologique nasale : filtration, drainage, immunité.</li></ul>","<div class=\"pgm\">p. 14</div><ul><li>évite que les mucosités descendent dans la gorge (raclement) et sur les bronches ;</li><li>renforce les défenses (effet décongestionnant du sel) ; assainit le rhinopharynx ;</li><li>redonne du grain à la voix ; prévient les refroidissements, garde sain le nerf olfactif ; aide au drainage et à la ventilation.</li></ul><h4>Matériel</h4><p>1 plateau, <b>1 seringue de 60 cc</b>, 1 canule, sérum physiologique froid (selon le cours), cupule stérile, gants, mouchoirs, alèse imperméable, bassin réniforme, serviette.</p><h4>Réalisation : nourrisson de moins de six mois</h4><p>Geste <b>indolore</b> mais désagréable. Se laver les mains ; <b>dosettes de sérum physiologique à usage unique</b> : eau minérale ou du robinet déconseillées (pas assez salées, germes). Cinq étapes :</p><p>1. <b>allonger bébé sur le dos ou sur le côté, tête maintenue sur le côté</b> pour éviter la <b>fausse route</b> (passage involontaire de</p><div class=\"pgm\">p. 15</div><p>sérum dans les voies respiratoires) ; se faire aider si besoin ;</p><p>2. embout de la dosette à l&#x27;entrée de la <b>narine située le plus haut</b> ;</p><p>3. presser la dosette en entier ; <b>fermer la bouche de l&#x27;enfant</b> : le sérum ressort par l&#x27;autre narine avec les sécrétions ;</p><p>4. attendre que bébé ait dégluti ;</p><p>5. essuyer le nez avec un mouchoir jetable.</p><p>Répéter pour l&#x27;autre narine avec <b>une autre dosette</b>, tête tournée de l&#x27;autre côté.</p><p><b>Le lavage de nez est préférable au mouche-bébé</b>, moins efficace car il débouche moins bien.</p><h4>Bébé à partir de six mois</h4><p>Même technique ; possible pulvérisateur de solution saline (eau de mer). <b>Sprays et solutions nasales avec vasoconstricteurs proscrits avant l&#x27;âge de 15 ans</b> (effets secondaires graves). Spray : pulvérisations sans pression trop forte ; nettoyer l&#x27;embout à l&#x27;eau chaude ; flacon à usage personnel.</p><p>Si seul(e), maintenir le bébé selon la technique suivante :</p><div class=\"pgm\">p. 16</div><ul><li>s&#x27;asseoir sur un lit, jambes allongées ;</li><li>placer l&#x27;enfant entre ses jambes, tête au niveau des cuisses, bras sous les cuisses ;</li><li>tourner la tête sur le côté, puis nettoyer.</li></ul><h4>L&#x27;enfant qui sait se moucher</h4><p>Sérum physiologique ou solution à pulvériser <b>sans vasoconstricteurs</b> ; l&#x27;enfant participe activement :</p><ul><li>assis, tête inclinée sur le côté ; embout dans la <b>narine la plus haute</b> ;</li><li>pression sur la dosette ou pulvérisation courte ; <b>se moucher fort</b> ; répéter de l&#x27;autre côté.</li></ul><p>Lavage à la pipette ou à la seringue : <b>tête à l&#x27;horizontale, tournée sur le côté</b> ; le sérum mis dans la narine du haut ressort par l&#x27;autre après la fosse nasale haute, le cavum, puis la fosse nasale basse. Puis souffler fortement par la narine basse en fermant l&#x27;autre avec le pouce.</p><p>Il faut d&#x27;abord tester : la première fois, possible désagrément, voire mal de tête : arrêter, réessayer le lendemain, à petites doses.</p><div class=\"pgm\">p. 17</div><h4>Lavage de nez chez l&#x27;adulte</h4><ul><li><b>position verticale</b>, tête inclinée sur le côté, embout dans la <b>narine supérieure</b> ;</li><li><b>pression franche</b> : le liquide s&#x27;écoule par l&#x27;autre narine ; laisser agir quelques secondes ;</li><li>renouveler de l&#x27;autre côté ; puis moucher.</li></ul><h4>Produits</h4><p>Eau du robinet (solutions du commerce chères) ; si doute : eau bouillie ou minérale [divergence avec le paragraphe nourrisson]. Température : <b>froid/tiède = renforcement des défenses ; tiède/chaud = dilatation et dégagement</b>. Sérum physiologique ; eau de mer diluée (1/3) ; eau de mer 100 %.</p><h4>Préparation (1 litre d&#x27;eau)</h4><p><b>Gros sel (pas le sel fin de table, qui contient des additifs) : 2 cuillères à café par litre</b> ; option : pincée de bicarbonate ; remuer, laisser reposer 1 min.</p><h4>Fréquence</h4><p><b>Cures d&#x27;une semaine tous les mois</b> ; de manière saisonnière ou en cas d&#x27;alerte.</p>","<div class=\"pgm\">p. 18</div><h4>MÉCHAGE ANTÉRIEUR OU TAMPONNEMENT ANTÉRIEUR</h4><p>Objectif : réaliser un méchage antérieur ; décrire la technique.</p><h4>I- Définition</h4><p><b>Pratiqué surtout dans les épistaxis : combler en accordéon les fosses nasales à l&#x27;aide d&#x27;une mèche, depuis les choanes jusqu&#x27;au vestibule, dans le but de faire l&#x27;hémostase.</b></p><h4>II- Indications</h4><ul><li><b>épistaxis</b> ; contention d&#x27;une réduction des OPN (os propres du nez) ; cavoscopie ; après chirurgie (cautérisation des cornets, turbinectomie, plastie…).</li></ul><h4>III- Matériel</h4><p>Plateau ; <b>spéculum de Palmer</b> ; <b>pince coudée de Lubet-Barbon</b> ou de Politzer ; ciseaux droits ; miroir de Clar ; <b>mèche de gaze de 2 à 3 cm de large</b> ou compresse découpée ; compresses stériles ; pulvérisateur de xylocaïne ; <b>xylocaïne 5 % à la naphazoline</b> ; pommade HEC ; gants d&#x27;examen ; bavettes ; haricot ; champ ; sparadrap.</p><h4>Préparation psychologique</h4><ul><li>rassurer ; <b>l&#x27;acte n&#x27;est pas douloureux</b> ; <b>sous anesthésie locale</b> ; <b>déméchage dans 48 heures</b>.</li></ul><div class=\"pgm\">p. 19</div><h4>IV- Technique</h4><ul><li><b>position assise ou demi-assise</b> ; protéger d&#x27;un champ ; haricot sous le menton ;</li><li>faire moucher pour évacuer les caillots ;</li><li><b>pulvérisation ou premier méchage à la xylocaïne, attendre 5 à 10 min</b> (rétracte les cornets, anesthésie les FN) ;</li><li>imbiber la mèche d&#x27;hémostatique ; mettre en place le spéculum de Palmer ;</li><li>saisir la mèche à 10 cm (« 10 m » dans le texte) de son extrémité et l&#x27;introduire au fond de la fosse nasale ;</li><li>poursuivre tantôt vers le haut, tantôt vers le bas jusqu&#x27;à combler la FN : <b>mèche tassée en accordéon</b> ;</li><li>maintenir avec compresses devant le nez et sparadrap ;</li><li><b>traitement général : ATB, antalgique, hémostatique</b> ;</li><li><b>déméchage au bout de 48 h</b>.</li></ul><p>[Figure : mèche en accordéon dans la fosse nasale]</p><h4>Conseils de sortie</h4><ul><li>FN bouchées : <b>respirer par la bouche pendant 48 h</b> ;</li><li>manger et boire lentement, par petites gorgées ;</li><li><b>sans traitement, les FN vont se surinfecter</b> ;</li><li>revenir s&#x27;il saigne à nouveau ; rassurer.</li></ul>","<div class=\"pgm\">p. 20</div><h4>SOINS DE TRACHÉOTOMIE</h4><p>Objectifs : citer au moins 3 indications ; citer 2 complications immédiates ; décrire l&#x27;entretien de la canule (indications et complications non développées dans le texte).</p><h4>I- Définition</h4><p><b>Ouverture de la trachée cervicale afin d&#x27;y introduire une canule ; elle sert à court-circuiter les voies aériennes supérieures lors d&#x27;un obstacle.</b></p><h4>D- Soins post-opératoires</h4><ul><li><b>aspiration des sécrétions</b> ;</li><li><b>humidification de l&#x27;air inspiré</b> ;</li><li>prévention de l&#x27;infection de la plaie et lutte contre l&#x27;infection broncho-pulmonaire par des soins de trachéotomie ;</li><li><b>canule à changer tous les 3 jours si possible</b> ;</li><li><b>sonde d&#x27;aspiration dans un bocal d&#x27;eau additionnée d&#x27;antiseptique (ex. Bétadine jaune)</b>.</li></ul><p>(Reste de la page blanc.)</p>"]});
